export default {"liubang": {"title": "刘邦", "revid": 94756962, "date": "2026-10-04", "brief": "刘邦（前256年或前247年—前195年6月1日），字季，原名刘季，沛丰邑中阳里（今江苏省丰县）人，中国秦末汉初的军事家、政治家，汉朝开国皇帝，也是中国历史上第一位平民阶级出身…", "img": {"src": "portraits/liubang.webp", "w": 240, "h": 317, "file": "File:Liu Bang (Emperor Gaozu of Han).png", "page": "https://commons.wikimedia.org/wiki/File:Liu_Bang_(Emperor_Gaozu_of_Han).png", "license": "Public domain", "artist": "Unknown author"}}, "luxunwriter": {"title": "鲁迅", "revid": 93388577, "date": "2026-07-09", "brief": "周树人（1881年9月25日—1936年10月19日），原名周樟寿，字豫山、豫亭，后改字豫才，笔名鲁迅，浙江绍兴人，中国近代作家、设计师、新文化运动领袖之一。", "img": {"src": "portraits/luxunwriter.webp", "w": 240, "h": 353, "file": "File:鲁迅 1933年5月26日摄于上海.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E9%B2%81%E8%BF%85_1933%E5%B9%B45%E6%9C%8826%E6%97%A5%E6%91%84%E4%BA%8E%E4%B8%8A%E6%B5%B7.jpg", "license": "Public domain", "artist": "雪怀照相馆"}}, "maozedong": {"title": "毛泽东", "revid": 94750004, "date": "2026-10-04", "brief": "毛泽东（1893年12月26日—1976年9月9日），字润之，湖南湘潭人，中国近现代马列主义理论家、革命家、政治家、军事战略家、诗人、书法家。", "img": {"src": "portraits/maozedong.webp", "w": 240, "h": 320, "file": "File:Mao Zedong 1950 Portrait (3x4 cropped).jpg", "page": "https://commons.wikimedia.org/wiki/File:Mao_Zedong_1950_Portrait_(3x4_cropped).jpg", "license": "Public domain", "artist": "Chen Zhengqing (1917–1966)"}}, "zhouenlai": {"title": "周恩来", "revid": 94698909, "date": "2026-10-02", "brief": "周恩来（1898年3月5日—1976年1月8日），字翔宇，小名大鸾，祖籍浙江绍兴，生于江苏淮安。", "img": {"src": "portraits/zhouenlai.webp", "w": 240, "h": 320, "file": "File:Zhou Enlai 1972.jpg", "page": "https://commons.wikimedia.org/wiki/File:Zhou_Enlai_1972.jpg", "license": "Public domain", "artist": "President (1969-1974 : Nixon). White House Photo Office. 1969-1974; General Services Administration. National Archives a"}}, "xiangyu": {"title": "项羽", "revid": 94342616, "date": "2026-09-13", "brief": "项羽（前232年—前202年），名籍，字羽，以字行，楚国下相（今江苏省宿迁市）人，秦朝末年至楚汉时期西楚的军事家、政治家，同时是西楚开国君主。", "img": {"src": "portraits/xiangyu.webp", "w": 240, "h": 240, "file": "File:Xiang Yu.png", "page": "https://commons.wikimedia.org/wiki/File:Xiang_Yu.png", "license": "Public domain", "artist": "Unknown author"}}, "hanxin": {"title": "韩信", "revid": 94609867, "date": "2026-09-27", "brief": "韩信（前231年—前196年），淮阴人，西汉开国功臣，与张良，萧何并称为汉初三杰；又与彭越、英布并称为汉初三大名将。", "img": {"src": "portraits/hanxin.webp", "w": 240, "h": 329, "file": "File:汉淮阴侯韩信.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E6%B1%89%E6%B7%AE%E9%98%B4%E4%BE%AF%E9%9F%A9%E4%BF%A1.jpg", "license": "Public domain", "artist": "Unknown author"}}, "zhangliang": {"title": "张良", "revid": 94330030, "date": "2026-09-13", "brief": "张良（？—前186年），字子房，颍川城父（今河南省平顶山市郏县）人。战国时代韩国人，韩国被秦朝灭亡后，曾暗杀秦始皇失败，后成为汉高祖刘邦的谋臣，是汉朝的开国元勋之一，与萧何、韩…", "img": {"src": "portraits/zhangliang.webp", "w": 218, "h": 502, "file": "File:张良像.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E5%BC%A0%E8%89%AF%E5%83%8F.jpg", "license": "CC BY-SA 4.0", "artist": "西汉画家"}}, "xiahe": {"title": "萧何", "revid": 94754501, "date": "2026-10-04", "brief": "萧何（？—前193年），沛县（今中国江苏省沛县）人。是汉朝初年相国、政治家。封爵酂侯，谥号文终，汉初三杰之一。辅助汉高祖刘邦建立汉政权。", "img": {"src": "portraits/xiahe.webp", "w": 240, "h": 323, "file": "File:汉相国酂侯萧何.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E6%B1%89%E7%9B%B8%E5%9B%BD%E9%85%82%E4%BE%AF%E8%90%A7%E4%BD%95.jpg", "license": "Public domain", "artist": "Unknown author"}}, "fanzeng": {"title": "范增", "revid": 94809662, "date": "2026-10-07", "brief": "范增（前277年—前204年），战国后期至秦末居巢（今安徽省巢湖市亚父街道）人，西楚霸王项羽首席谋臣幕僚。", "img": {"src": "portraits/fanzeng.webp", "w": 240, "h": 349, "file": "File:WUL-he21 01467 新鐫繪像東西漢全傳 01 (范增).jpg", "page": "https://commons.wikimedia.org/wiki/File:WUL-he21_01467_%E6%96%B0%E9%90%AB%E7%B9%AA%E5%83%8F%E6%9D%B1%E8%A5%BF%E6%BC%A2%E5%85%A8%E5%82%B3_01_(%E8%8C%83%E5%A2%9E).jpg", "license": "Public domain", "artist": "鍾 惺, 1574-1624"}}, "zhugeliang": {"title": "诸葛亮", "revid": 94687021, "date": "2026-10-01", "brief": "诸葛亮（181年—234年10月8日），字孔明，琅琊郡阳都县（今山东省临沂市沂南县）人。", "img": {"src": "portraits/zhugeliang.webp", "w": 240, "h": 325, "file": "File:蜀汉丞相忠武侯诸葛亮.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E8%9C%80%E6%B1%89%E4%B8%9E%E7%9B%B8%E5%BF%A0%E6%AD%A6%E4%BE%AF%E8%AF%B8%E8%91%9B%E4%BA%AE.jpg", "license": "Public domain", "artist": "Unknown author"}}, "confucius": {"title": "孔子", "revid": 94623001, "date": "2026-09-28", "brief": "孔子（前551年9月28日—前479年3月9日），姓子，氏孔，名丘，字仲尼，后世敬称孔子或孔夫子，中国春秋时代鲁国官员、思想家和教育家。", "img": {"src": "portraits/confucius.webp", "w": 240, "h": 296, "file": "File:孔子燕居像.png", "page": "https://commons.wikimedia.org/wiki/File:%E5%AD%94%E5%AD%90%E7%87%95%E5%B1%85%E5%83%8F.png", "license": "Public domain", "artist": "Unknown author"}}, "sunwu": {"title": "孙武", "revid": 93644491, "date": "2026-07-25", "brief": "孙武（前545年—前470年或前496年），妫姓，孙氏，名武，字长卿，春秋时期齐国人，陈胡公的直系后代，著名军事家、政治家，兵家代表人物。", "img": {"src": "portraits/sunwu.webp", "w": 240, "h": 261, "file": "File:吴司马孙武.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E5%90%B4%E5%8F%B8%E9%A9%AC%E5%AD%99%E6%AD%A6.jpg", "license": "Public domain", "artist": "Unknown author"}}, "shangyang": {"title": "商鞅", "revid": 93876564, "date": "2026-08-13", "brief": "商鞅（前390年—前338年），又称卫鞅或公孙鞅，是战国中期卫国人，公元前4世纪的重要政治家和军事家，也是法家代表人物之一，师从李悝。", "img": {"src": "portraits/shangyang.webp", "w": 240, "h": 357, "file": "File:Statue of Shang Yang.jpg", "page": "https://commons.wikimedia.org/wiki/File:Statue_of_Shang_Yang.jpg", "license": "CC BY 2.5", "artist": "Taken by Fanghong"}}, "quyuan": {"title": "屈原", "revid": 94244798, "date": "2026-09-08", "brief": "屈原（约前340年－前278年），芈姓，屈氏，名平，字原，是中国战国时期楚国的诗人、政治人物。现存最早提及屈原的作品是西汉贾谊的《吊屈原赋》；", "img": {"src": "portraits/quyuan.webp", "w": 240, "h": 324, "file": "File:楚三闾大夫屈原.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E6%A5%9A%E4%B8%89%E9%97%BE%E5%A4%A7%E5%A4%AB%E5%B1%88%E5%8E%9F.jpg", "license": "Public domain", "artist": "Unknown author"}}, "qinst": {"title": "秦始皇", "revid": 94788854, "date": "2026-10-06", "brief": "秦始皇（前259年2月18日—前210年7月11日），嬴姓，名政，史书多作秦王政或始皇帝。", "img": {"src": "portraits/qinst.webp", "w": 240, "h": 360, "file": "File:Qinshihuang.jpg", "page": "https://commons.wikimedia.org/wiki/File:Qinshihuang.jpg", "license": "Public domain", "artist": "Unknown artist"}}, "hanwudi": {"title": "汉武帝", "revid": 94598209, "date": "2026-09-27", "brief": "汉武帝刘彻（前156年－前87年），中国汉朝（西汉）皇帝，于公元前141年至前87年在位，共在位54年。汉武帝为汉景帝刘启第十子，母孝景王皇后。", "img": {"src": "portraits/hanwudi.webp", "w": 240, "h": 369, "file": "File:三才圖會 漢武帝劉徹相.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E4%B8%89%E6%89%8D%E5%9C%96%E6%9C%83_%E6%BC%A2%E6%AD%A6%E5%B8%9D%E5%8A%89%E5%BE%B9%E7%9B%B8.jpg", "license": "Public domain", "artist": "Wang Qi"}}, "simqian": {"title": "司馬遷", "revid": 94738211, "date": "2026-10-03", "brief": "司马迁（前145年—前86年？），字子长（cháng），世称“史迁”、“太史公”、“历史之父”，龙门（今陕西韩城）人，西汉史学家和文学家。", "img": {"src": "portraits/simqian.webp", "w": 240, "h": 244, "file": "File:Sima Qian (painted portrait).jpg", "page": "https://commons.wikimedia.org/wiki/File:Sima_Qian_(painted_portrait).jpg", "license": "Public domain", "artist": "佚名"}}, "caocao": {"title": "曹操", "revid": 94309238, "date": "2026-09-12", "brief": "曹操（155年—220年3月15日），字孟德，小字阿瞒，沛国谯县（今安徽亳州）人。", "img": {"src": "portraits/caocao.webp", "w": 240, "h": 367, "file": "File:Cao Cao scth.jpg", "page": "https://commons.wikimedia.org/wiki/File:Cao_Cao_scth.jpg", "license": "Public domain", "artist": "Wang Qi"}}, "liubei": {"title": "刘备", "revid": 94821588, "date": "2026-10-07", "brief": "汉昭烈帝刘备（161年—223年6月10日），字玄德，涿郡涿县（今河北省涿州市）人，三国时代蜀汉的开国皇帝，在位三年。谥号昭烈皇帝，庙号烈祖。", "img": {"src": "portraits/liubei.webp", "w": 240, "h": 346, "file": "File:Liu Bei Tang.jpg", "page": "https://commons.wikimedia.org/wiki/File:Liu_Bei_Tang.jpg", "license": "Public domain", "artist": "Yan Liben (閻立本)"}}, "sunquan": {"title": "孙权", "revid": 94460901, "date": "2026-09-20", "brief": "吴大帝孙权（182年7月5日—252年5月21日），字仲谋，生于下邳（今江苏省徐州市睢宁县北郊），籍贯吴郡富春。", "img": {"src": "portraits/sunquan.webp", "w": 240, "h": 326, "file": "File:Sun Quan Tang.jpg", "page": "https://commons.wikimedia.org/wiki/File:Sun_Quan_Tang.jpg", "license": "Public domain", "artist": "Yan Liben"}}, "suiwendi": {"title": "杨坚", "revid": 94537086, "date": "2026-09-24", "brief": "隋文帝杨坚（541年7月21日—604年8月13日），因父亲杨忠被西魏恭帝赐鲜卑姓，又名普六茹坚，小字那罗延，弘农郡华阴县（今陕西省华阴市）人。", "img": {"src": "portraits/suiwendi.webp", "w": 240, "h": 354, "file": "File:Sui Wendi Tang.jpg", "page": "https://commons.wikimedia.org/wiki/File:Sui_Wendi_Tang.jpg", "license": "Public domain", "artist": "Yan Li-pen"}}, "lshimin": {"title": "唐太宗", "revid": 94517110, "date": "2026-09-23", "brief": "李世民（598年—649年7月10日），唐高祖李渊次子，唐朝第二位皇帝。隋末随父起兵，参与统一战争。626年发动玄武门之变，杀太子李建成，受禅即位。", "img": {"src": "portraits/lshimin.webp", "w": 240, "h": 497, "file": "File:TangTaizong.jpg", "page": "https://commons.wikimedia.org/wiki/File:TangTaizong.jpg", "license": "Public domain", "artist": "Unknown artist"}}, "wuzetian": {"title": "武则天", "revid": 94806601, "date": "2026-10-06", "brief": "武曌（?—705年12月16日），通称武则天、武后，原名不详，赐号武媚，亦称武媚娘、天后等，籍贯并州文水县（今山西省文水县），出生时间及出生地有争议，武周的开国皇帝、唐高宗的皇…", "img": {"src": "portraits/wuzetian.webp", "w": 240, "h": 425, "file": "File:唐后行從圖 (局部) - 武則天.png", "page": "https://commons.wikimedia.org/wiki/File:%E5%94%90%E5%90%8E%E8%A1%8C%E5%BE%9E%E5%9C%96_(%E5%B1%80%E9%83%A8)_-_%E6%AD%A6%E5%89%87%E5%A4%A9.png", "license": "Public domain", "artist": "Likely to be Zhang Xuan (张萱)"}}, "libai": {"title": "李白", "revid": 94207726, "date": "2026-09-05", "brief": "李白（701年—762年），字太白，号称“诗仙”，自号“青莲居士”，唐朝诗人。李白的家世根据不同学者的考证和推论，有“蜀地汉人”、“西域汉人”及“西域外族”等说。", "img": {"src": "portraits/libai.webp", "w": 240, "h": 397, "file": "File:LiBai.jpg", "page": "https://commons.wikimedia.org/wiki/File:LiBai.jpg", "license": "Public domain", "artist": "Liang Kai"}}, "zhaokuangyin": {"title": "赵匡胤", "revid": 94222865, "date": "2026-09-06", "brief": "宋太祖赵匡胤（yìn）（927年3月21日—976年11月14日），祖籍涿郡（今河北省保定市清苑区一带），中国北宋开国皇帝。父亲为赵弘殷，母亲为杜氏。", "img": {"src": "portraits/zhaokuangyin.webp", "w": 240, "h": 269, "file": "File:Song Taizu.jpg", "page": "https://commons.wikimedia.org/wiki/File:Song_Taizu.jpg", "license": "Public domain", "artist": "AnonymousUnknown author"}}, "wanganshi": {"title": "王安石", "revid": 94291713, "date": "2026-09-11", "brief": "王安石（1021年12月19日—1086年5月21日），字介甫，号半山，抚州临川县盐阜岭（今江西省抚州市临川区）人，北宋著名政治家、文学家、思想家、改革家，实官至司空、尚书左仆…", "img": {"src": "portraits/wanganshi.webp", "w": 240, "h": 332, "file": "File:歷代聖賢名人像-29-宋丞相王荆公安石.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E6%AD%B7%E4%BB%A3%E8%81%96%E8%B3%A2%E5%90%8D%E4%BA%BA%E5%83%8F-29-%E5%AE%8B%E4%B8%9E%E7%9B%B8%E7%8E%8B%E8%8D%86%E5%85%AC%E5%AE%89%E7%9F%B3.jpg", "license": "Public domain", "artist": "Unknown author"}}, "sushi": {"title": "苏轼", "revid": 93777714, "date": "2026-08-05", "brief": "苏轼（1037年1月8日—1101年8月24日），字子瞻，一字和仲，号东坡居士、铁冠道人，眉州眉山（今四川省眉山市）人，北宋文学家、政治家、艺术家。", "img": {"src": "portraits/sushi.webp", "w": 240, "h": 565, "file": "File:Su shi.jpg", "page": "https://commons.wikimedia.org/wiki/File:Su_shi.jpg", "license": "Public domain", "artist": "Zhao Mengfu"}}, "yuefei": {"title": "岳飞", "revid": 94586720, "date": "2026-09-26", "brief": "岳飞（1103年3月24日—1142年1月27日），字鹏举，宋朝相州汤阴（今河南省安阳市汤阴县）人。南宋抗金名将及民族英雄，官至少保、枢密副使，受封武昌郡开国公。", "img": {"src": "portraits/yuefei.webp", "w": 240, "h": 502, "file": "File:岳飛.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E5%B2%B3%E9%A3%9B.jpg", "license": "CC BY-SA 4.0", "artist": "劉松年繪"}}, "kublai": {"title": "忽必烈", "revid": 94749062, "date": "2026-10-04", "brief": "元世祖忽必烈（蒙古语：ᠬᠤᠪᠢᠯᠠᠢᠬᠠᠭᠠᠨ，汉语拼音字母：HûbilaiHaan，鲍培转写：Qubilaiqaγan，秘史记音：中忽必来，西里尔字母：Хубилайхаан…", "img": {"src": "portraits/kublai.webp", "w": 240, "h": 300, "file": "File:YuanEmperorAlbumKhubilaiPortrait.jpg", "page": "https://commons.wikimedia.org/wiki/File:YuanEmperorAlbumKhubilaiPortrait.jpg", "license": "Public domain", "artist": "Araniko"}}, "zhuyuanzhang": {"title": "朱元璋", "revid": 94233522, "date": "2026-09-07", "brief": "明太祖朱元璋（1328年10月21日—1398年6月24日），字国瑞，濠州钟离县（今安徽省凤阳县）人，中国元末明初政治家、军事家、诗人与农民起义领袖，是中国历史人物、明朝的开国…", "img": {"src": "portraits/zhuyuanzhang.webp", "w": 240, "h": 391, "file": "File:Portrait assis de l'empereur Ming Taizu.jpg", "page": "https://commons.wikimedia.org/wiki/File:Portrait_assis_de_l%27empereur_Ming_Taizu.jpg", "license": "Public domain", "artist": "Unknown author"}}, "zhudi": {"title": "明成祖", "revid": 93973381, "date": "2026-08-20", "brief": "明成祖朱棣（1360年5月2日—1424年8月12日），南直隶凤阳府（今安徽省凤阳县）人，生于应天府（今江苏省南京市），中国明初政治家与军事家，明太祖朱元璋第四子，明朝第三位皇…", "img": {"src": "portraits/zhudi.webp", "w": 240, "h": 348, "file": "File:Portrait assis de l'empereur Ming Chengzu.jpg", "page": "https://commons.wikimedia.org/wiki/File:Portrait_assis_de_l%27empereur_Ming_Chengzu.jpg", "license": "Public domain", "artist": "Unknown author"}}, "wangyangming": {"title": "王陽明", "revid": 94052211, "date": "2026-08-26", "brief": "王守仁（1472年10月31日—1529年1月9日），幼名云，字伯安，号阳明子，浙江绍兴府余姚县（今浙江省余姚市）人，明代中期乃至中国历史上重要和影响深远的思想家、哲学家、书法…", "img": {"src": "portraits/wangyangming.webp", "w": 240, "h": 315, "file": "File:蔡世新 王阳明肖像轴 (cropped).jpg", "page": "https://commons.wikimedia.org/wiki/File:%E8%94%A1%E4%B8%96%E6%96%B0_%E7%8E%8B%E9%98%B3%E6%98%8E%E8%82%96%E5%83%8F%E8%BD%B4_(cropped).jpg", "license": "Public domain", "artist": "Cai Shixin"}}, "zhangjuzheng": {"title": "張居正", "revid": 94193378, "date": "2026-09-04", "brief": "张居正（1525年5月26日—1582年7月9日），字叔大，号太岳，人称张江陵，湖广荆州府江陵县（今湖北荆州江陵县）人，荆州卫军籍。", "img": {"src": "portraits/zhangjuzheng.webp", "w": 240, "h": 356, "file": "File:張居正-清晰版.jpeg", "page": "https://commons.wikimedia.org/wiki/File:%E5%BC%B5%E5%B1%85%E6%AD%A3-%E6%B8%85%E6%99%B0%E7%89%88.jpeg", "license": "Public domain", "artist": "Rongshi"}}, "zhenghe": {"title": "鄭和", "revid": 92754082, "date": "2026-05-22", "brief": "郑和（1371年9月23日—1433年），原姓马，小名三宝，又作三保，云南昆阳县（今云南省昆明市晋宁区）人，明成祖赐姓郑，故称郑和。中国明朝军事家、航海家、外交家及宦官。", "img": {"src": "portraits/zhenghe.webp", "w": 240, "h": 360, "file": "File:2016 Malakka, Stadhuys (09).jpg", "page": "https://commons.wikimedia.org/wiki/File:2016_Malakka,_Stadhuys_(09).jpg", "license": "CC BY-SA 4.0", "artist": "Marcin Konsek"}}, "kangxi": {"title": "康熙", "revid": 92805992, "date": "2026-05-26", "brief": "康熙（满语：ᡝᠯᡥᡝᡨ᠋ᠠᡳ᠌ᡶ᠋ᡳᠨ，穆麟德转写：elhetaifin；蒙古语：ᠡᠩᠬᠡᠠᠮᠤᠭᠤᠯᠠᠩ，汉语拼音字母：EnghAmgalang，鲍培转写：engkeamuγ…"}, "yongzheng": {"title": "雍正", "revid": 92806078, "date": "2026-05-26", "brief": "雍正（满语：ᡥᡡᠸᠠᠯᡳᠶᠠᠰᡠᠨᡨ᠋ᠣᠪ，穆麟德转写：hūwaliyasuntob，大词典转写：huuwaliyasuntob；"}, "qianlong": {"title": "乾隆", "revid": 92806114, "date": "2026-05-26", "brief": "乾隆（满语：ᠠᠪᡴᠠᡳᠸᡝᡥᡳᠶᡝᡥᡝ，罗马化：abkaiwehiyehe；蒙古语：ᠲᠩᠷᠢᠶᠢᠨᠲᠡᠳᠭᠦᠭᠰᠡᠨ，汉语拼音字母：Tengger-iinTetgesen，鲍培…"}, "linzexu": {"title": "林则徐", "revid": 93187041, "date": "2026-06-24", "brief": "林则徐（1785年8月30日—1850年11月22日），字元抚，又字少穆、石麟，晚号俟村老人、俟村退叟、七十二峰退叟、瓶泉居士、栎社散人等，男，福建省福州府侯官县左营司巷（今福…", "img": {"src": "portraits/linzexu.webp", "w": 240, "h": 284, "file": "File:Portrait of Lin Zexu.jpeg", "page": "https://commons.wikimedia.org/wiki/File:Portrait_of_Lin_Zexu.jpeg", "license": "Public domain", "artist": "Lam Qua"}}, "zengguofan": {"title": "曾国藩", "revid": 92940727, "date": "2026-06-04", "brief": "曾国藩（1811年11月26日—1872年3月12日），原名子城，字伯涵，号涤生，斋名求阙斋，湖南湘乡人（今双峰县荷叶镇）。", "img": {"src": "portraits/zengguofan.webp", "w": 240, "h": 340, "file": "File:Tseng Kwo-Fan.tif", "page": "https://commons.wikimedia.org/wiki/File:Tseng_Kwo-Fan.tif", "license": "Public domain", "artist": "Unknown author"}}, "laozi": {"title": "老子", "revid": 94869835, "date": "2026-10-09", "brief": "李聃（dān）（前571年—不详），李氏，一说姓老，一说姓利，名耳或贞，字耼。一称老耼，一字伯阳。世人尊称其为“老子”。", "img": {"src": "portraits/laozi.webp", "w": 240, "h": 438, "file": "File:Zhang Lu-Laozi Riding an Ox.jpg", "page": "https://commons.wikimedia.org/wiki/File:Zhang_Lu-Laozi_Riding_an_Ox.jpg", "license": "Public domain", "artist": "Zhang Lu"}}, "mozi": {"title": "墨子", "revid": 93640740, "date": "2026-07-25", "brief": "墨子（前468年？—前376年），子姓，墨氏，名翟，春秋末战国初期宋国（今河南商丘）人，一说鲁国（今山东滕州木石镇）人，是中国著名思想家、科学家、教育家、军事家、通才。", "img": {"src": "portraits/mozi.webp", "w": 240, "h": 240, "file": "File:Философ Мо-Цзы.jpg", "page": "https://commons.wikimedia.org/wiki/File:%D0%A4%D0%B8%D0%BB%D0%BE%D1%81%D0%BE%D1%84_%D0%9C%D0%BE-%D0%A6%D0%B7%D1%8B.jpg", "license": "CC0", "artist": "Vjacheslav Rublevskiy"}}, "mencius": {"title": "孟子", "revid": 94044007, "date": "2026-08-25", "brief": "孟子（前372年—前289年），姬姓，孟氏，名轲，邹国（今山东省邹城市）人，战国时期儒家代表人物。", "img": {"src": "portraits/mencius.webp", "w": 240, "h": 325, "file": "File:Half Portraits of the Great Sage and Virtuous Men of Old - Meng Ke (孟軻).jpg", "page": "https://commons.wikimedia.org/wiki/File:Half_Portraits_of_the_Great_Sage_and_Virtuous_Men_of_Old_-_Meng_Ke_(%E5%AD%9F%E8%BB%BB).jpg", "license": "Public domain", "artist": "anonymous"}}, "zhuangzi": {"title": "庄子", "revid": 94107459, "date": "2026-08-30", "brief": "庄子（约前369年—前286年），庄氏，名周，一说字子休，约与孟子同时，宋国蒙人（今山东省菏泽市东明县），曾任漆园吏。", "img": {"src": "portraits/zhuangzi.webp", "w": 240, "h": 345, "file": "File:玄門十子圖 莊子.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E7%8E%84%E9%96%80%E5%8D%81%E5%AD%90%E5%9C%96_%E8%8E%8A%E5%AD%90.jpg", "license": "Public domain", "artist": "Hua Zili (華祖立)"}}, "xunzi": {"title": "荀子", "revid": 94714465, "date": "2026-10-02", "brief": "荀子（约公元前316年—约公元前237年至公元前235年），名况，被尊称为荀卿，又称孙卿，中国战国时代儒家学者和思想家，赵国人，曾担任齐国稷下学宫祭酒、楚国兰陵令，到赵国、秦国…", "img": {"src": "portraits/xunzi.webp", "w": 240, "h": 331, "file": "File:战国时楚兰陵令荀况.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E6%88%98%E5%9B%BD%E6%97%B6%E6%A5%9A%E5%85%B0%E9%99%B5%E4%BB%A4%E8%8D%80%E5%86%B5.jpg", "license": "Public domain", "artist": "Unknown author"}}, "hanfei": {"title": "韩非", "revid": 94458856, "date": "2026-09-20", "brief": "韩非（约前281年—前233年），为中国战国末期韩国的宗室公子，又称公子非。思想家，为中国古代法家思想的代表人物，认为应该要“法”、“术”、“势”三者并重，是法家的集大成者。", "img": {"src": "portraits/hanfei.webp", "w": 240, "h": 359, "file": "File:Statue Of Han Fei.png", "page": "https://commons.wikimedia.org/wiki/File:Statue_Of_Han_Fei.png", "license": "CC BY-SA 4.0", "artist": "Sabinowitz"}}, "guanzhong": {"title": "管仲", "revid": 93876580, "date": "2026-08-13", "brief": "管仲（前725年—前645年），姬姓，管氏，名夷吾，字仲，以字行，谥敬，通称为管子、管夷吾、管敬仲，颍上（今安徽省颍上县）人，春秋时期法家代表人物。", "img": {"src": "portraits/guanzhong.webp", "w": 240, "h": 343, "file": "File:Guan Zhong.png", "page": "https://commons.wikimedia.org/wiki/File:Guan_Zhong.png", "license": "Public domain", "artist": "Unknown author"}}, "wuzixu": {"title": "伍子胥", "revid": 94745935, "date": "2026-10-04", "brief": "伍子胥（前559年—前484年），伍氏。名员（yún），字子胥，以字行，后投奔吴国，封于申，因此又叫申胥。伍子胥家族因在楚国被迫害，投奔吴国。", "img": {"src": "portraits/wuzixu.webp", "w": 240, "h": 324, "file": "File:Wu Yun (Wu Zixu).png", "page": "https://commons.wikimedia.org/wiki/File:Wu_Yun_(Wu_Zixu).png", "license": "Public domain", "artist": "Unknown author"}}, "goujian": {"title": "勾践", "revid": 94068023, "date": "2026-08-27", "brief": "勾践（？—前464年），又写作句践；在出土文物“越王勾践剑”里写为鸠浅；司马贞《史记索隐》引《纪年》作菼执，是中国春秋时代后期的越国君主。", "img": {"src": "portraits/goujian.webp", "w": 240, "h": 328, "file": "File:NJlib-0026095-0001 東周列國志二十七卷一百八回圖二卷 (勾踐).jpg", "page": "https://commons.wikimedia.org/wiki/File:NJlib-0026095-0001_%E6%9D%B1%E5%91%A8%E5%88%97%E5%9C%8B%E5%BF%97%E4%BA%8C%E5%8D%81%E4%B8%83%E5%8D%B7%E4%B8%80%E7%99%BE%E5%85%AB%E5%9B%9E%E5%9C%96%E4%BA%8C%E5%8D%B7_(%E5%8B%BE%E8%B8%90).jpg", "license": "Public domain", "artist": "清蔡奡評點"}}, "lianpo": {"title": "廉颇", "revid": 92238397, "date": "2026-04-10", "brief": "廉颇（pō）（前327年—前243年），嬴姓，廉氏，名颇，字洪野，晋系金文作𡉣波，籍贯有山西太原、山西运城、山东德州等说。", "img": {"src": "portraits/lianpo.webp", "w": 240, "h": 298, "file": "File:廉頗.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E5%BB%89%E9%A0%97.jpg", "license": "Public domain", "artist": "馮夢龍"}}, "limu": {"title": "李牧", "revid": 92841289, "date": "2026-05-29", "brief": "李牧（？—前229年），名繓（zuǒ），字牧，以字行，战国后期军事家，赵国名将，与白起、王翦、廉颇并称战国四名将。", "img": {"src": "portraits/limu.webp", "w": 240, "h": 276, "file": "File:Li Mu1.jpg", "page": "https://commons.wikimedia.org/wiki/File:Li_Mu1.jpg", "license": "Public domain", "artist": "anonymous"}}, "baiqi": {"title": "白起", "revid": 93655100, "date": "2026-07-26", "brief": "白起（前332年？—前257年11月），白氏，又称公孙起，郿县（今陕西省眉县常兴镇白家村）人，战国时代军事家、秦国名将，兵家代表人物。", "img": {"src": "portraits/baiqi.webp", "w": 240, "h": 321, "file": "File:白起像（明人绘）.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E7%99%BD%E8%B5%B7%E5%83%8F%EF%BC%88%E6%98%8E%E4%BA%BA%E7%BB%98%EF%BC%89.jpg", "license": "Public domain", "artist": "Unknown author"}}, "lvhou": {"title": "吕雉", "revid": 93722688, "date": "2026-08-01", "brief": "吕氏（前241？—前180年8月18日），字娥姁，一说名雉。汉高祖刘邦皇后。通称吕后，或称汉高后、吕太后、高皇后。东汉时光武帝追尊薄太后为高皇后，追废吕后为高后。", "img": {"src": "portraits/lvhou.webp", "w": 240, "h": 340, "file": "File:WUL-he21 01467 新鐫繪像東西漢全傳 01 (呂后).jpg", "page": "https://commons.wikimedia.org/wiki/File:WUL-he21_01467_%E6%96%B0%E9%90%AB%E7%B9%AA%E5%83%8F%E6%9D%B1%E8%A5%BF%E6%BC%A2%E5%85%A8%E5%82%B3_01_(%E5%91%82%E5%90%8E).jpg", "license": "Public domain", "artist": "鍾 惺, 1574-1624"}}, "chenping": {"title": "陈平 (汉朝)", "revid": 94035502, "date": "2026-08-25", "brief": "陈平（前3世纪?—前178年），阳武（今山东省菏泽市东明县）人，以谋略见长。在楚汉相争时，初在项羽手下做谋士。早期被项羽重用，因得罪亚父范增，逃归汉王刘邦帐下。", "img": {"src": "portraits/chenping.webp", "w": 240, "h": 269, "file": "File:Chen Ping, Marquis of Quni.jpg", "page": "https://commons.wikimedia.org/wiki/File:Chen_Ping,_Marquis_of_Quni.jpg", "license": "Public domain", "artist": "Unknown author"}}, "huoqubing": {"title": "霍去病", "revid": 94839123, "date": "2026-10-08", "brief": "霍去病（前140年—前117年），河东郡平阳县（今山西临汾）人，卫子夫的姨甥，卫青的外甥，霍光之兄，西汉汉武帝时代对抗匈奴的名将。元狩六年因病去世，年仅二十三岁。", "img": {"src": "portraits/huoqubing.webp", "w": 240, "h": 343, "file": "File:渡河受款.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E6%B8%A1%E6%B2%B3%E5%8F%97%E6%AC%BE.jpg", "license": "Public domain", "artist": "Ma Tai (馬駘; C.E.1885-1937)"}}, "weiqing": {"title": "卫青", "revid": 92141932, "date": "2026-04-02", "brief": "卫青（？—前106年），本姓郑，字仲卿，河东郡平阳县（今山西省临汾市西南）人，西汉汉武帝时期军事家，是汉匈战争早期击溃匈奴的重要功臣，官至大将军，加官大司马，封长平侯，食禄万户…"}, "wangzhaojun": {"title": "王昭君", "revid": 92316138, "date": "2026-04-17", "brief": "王昭君（前51年—前15年），名嫱，字昭君，以字行，西汉南郡秭归（今湖北省兴山县）人，汉元帝时期的宫女、和亲女性，古代四大美人之一。“画工弃市”记载她的生平典故。", "img": {"src": "portraits/wangzhaojun.webp", "w": 240, "h": 348, "file": "File:Wang Zhaojun.png", "page": "https://commons.wikimedia.org/wiki/File:Wang_Zhaojun.png", "license": "Public domain", "artist": "佚名"}}, "banchao": {"title": "班超", "revid": 93499658, "date": "2026-07-16", "brief": "班超（32年—102年），字仲升，右扶风平陵县（今陕西省咸阳市秦都区）人，东汉将领、外交家。是开拓和维持汉代与西域关系的重要人物。", "img": {"src": "portraits/banchao.webp", "w": 240, "h": 512, "file": "File:汉班超立像.png", "page": "https://commons.wikimedia.org/wiki/File:%E6%B1%89%E7%8F%AD%E8%B6%85%E7%AB%8B%E5%83%8F.png", "license": "Public domain", "artist": "Unknown artist"}}, "zhangheng": {"title": "张衡", "revid": 92022079, "date": "2026-03-24", "brief": "张衡（78年—139年），字平子，南阳郡西鄂县（今河南省南阳市南召县南）人，东汉士大夫、天文学家、地理学家、数学家、科学家、发明家及文学家，官至太史令、侍中、尚书。"}, "cailun": {"title": "蔡伦", "revid": 92553243, "date": "2026-05-06", "brief": "蔡伦（63年—121年），字敬仲，桂阳郡耒阳（今湖南省耒阳市）人，东汉宦官。蔡伦改良了造纸技术，扩大了造纸原料的来源，把树皮、破布、麻头和鱼网这些废弃物品都充分利用起来，降低了…", "img": {"src": "portraits/cailun.webp", "w": 240, "h": 180, "file": "File:Wzbwgcailun.png", "page": "https://commons.wikimedia.org/wiki/File:Wzbwgcailun.png", "license": "CC BY-SA 3.0", "artist": "Caidiyun"}}, "liuxiu": {"title": "汉光武帝", "revid": 93726355, "date": "2026-08-01", "brief": "汉光武帝刘秀（前5年1月15日—57年3月29日），字文叔，南阳郡蔡阳县人（今湖北省枣阳市），东汉开国皇帝，25年8月5日至57年3月29日在位。庙号世祖，谥号光武皇帝。", "img": {"src": "portraits/liuxiu.webp", "w": 240, "h": 310, "file": "File:Han Guangwu Di.jpg", "page": "https://commons.wikimedia.org/wiki/File:Han_Guangwu_Di.jpg", "license": "Public domain", "artist": "Yan Li-pen"}}, "huoguang": {"title": "霍光", "revid": 94703708, "date": "2026-10-02", "brief": "霍光（？—前68年4月21日），字子孟，西汉河东郡平阳县（今山西省临汾市）人，政治家，麒麟阁十一功臣之首，名将霍去病异母弟，昭帝上官皇后外祖父，宣帝霍皇后之父。", "img": {"src": "portraits/huoguang.webp", "w": 240, "h": 401, "file": "File:Huo guang.jpg", "page": "https://commons.wikimedia.org/wiki/File:Huo_guang.jpg", "license": "Public domain", "artist": "Wang Qi"}}, "guanyu": {"title": "关羽", "revid": 94103876, "date": "2026-08-30", "brief": "关羽（?年—220年1月或2月），字云长，本字长生，司隶河东解县人（今山西运城），东汉末年将领，刘备的重要部将。《三国志》称关羽、张飞“皆称万人敌，为世虎臣”。", "img": {"src": "portraits/guanyu.webp", "w": 240, "h": 273, "file": "File:Guanyu-1.jpg", "page": "https://commons.wikimedia.org/wiki/File:Guanyu-1.jpg", "license": "Public domain", "artist": "UnknownUnknown , uploaded by Tiangong83 on zh.wikipedia"}}, "zhangfei": {"title": "张飞", "revid": 94093685, "date": "2026-08-29", "brief": "张飞（？—221年），字益德，东汉末年幽州涿郡（今河北省涿州市）人氏，汉末三国时期蜀汉名将，亦是刘备的主要亲信之一，与关羽并称“万人敌”。", "img": {"src": "portraits/zhangfei.webp", "w": 240, "h": 511, "file": "File:故宫南薰殿张飞画像.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E6%95%85%E5%AE%AB%E5%8D%97%E8%96%B0%E6%AE%BF%E5%BC%A0%E9%A3%9E%E7%94%BB%E5%83%8F.jpg", "license": "Public domain", "artist": "明代画师"}}, "zhaoyun": {"title": "赵云", "revid": 94570385, "date": "2026-09-26", "brief": "赵云（？年—229年），字子龙，是汉末三国时期的蜀汉武将，生于常山真定（今河北省正定县），据《赵云别传》记载，赵云身长八尺，姿颜雄伟。", "img": {"src": "portraits/zhaoyun.webp", "w": 240, "h": 584, "file": "File:ZhaoYun.jpg", "page": "https://commons.wikimedia.org/wiki/File:ZhaoYun.jpg", "license": "Public domain", "artist": "Unknown author"}}, "zhouyu": {"title": "周瑜", "revid": 94817945, "date": "2026-10-07", "brief": "周瑜（175年—210年），字公瑾，人称“周郎”，庐江郡舒县（今安徽省舒城县）人，东汉末年孙吴阵营首要的统帅。", "img": {"src": "portraits/zhouyu.webp", "w": 240, "h": 447, "file": "File:ZhouYu.jpg", "page": "https://commons.wikimedia.org/wiki/File:ZhouYu.jpg", "license": "Public domain", "artist": "Unknown author"}}, "simayi": {"title": "司马懿", "revid": 94569333, "date": "2026-09-25", "brief": "司马懿（179年—251年9月7日），字仲达，河内郡温县（今河南省焦作市温县）人，三国时期曹魏太傅、政治家、军事家，亦是日后西晋的奠基人。", "img": {"src": "portraits/simayi.webp", "w": 240, "h": 298, "file": "File:魏·太傅 司馬懿.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E9%AD%8F%C2%B7%E5%A4%AA%E5%82%85_%E5%8F%B8%E9%A6%AC%E6%87%BF.jpg", "license": "Public domain", "artist": "Ming Zhu Tianran"}}, "luxun": {"title": "陸遜", "revid": 94520817, "date": "2026-09-23", "brief": "陆逊（183年—245年3月19日），本名陆议，字伯言，吴郡吴县（今江苏省苏州市）人，三国时代吴国军事家、政治家，负责统领吴国军事和政治多年，并同时掌管民事，辅佐太子等。"}, "caopi": {"title": "曹丕", "revid": 93413926, "date": "2026-07-11", "brief": "魏文帝曹丕（187年—226年6月29日），字子桓，沛国谯县（今属安徽省亳州市）人。三国时期曹魏的开国皇帝，是曹操和武宣卞皇后的嫡长子。", "img": {"src": "portraits/caopi.webp", "w": 240, "h": 329, "file": "File:Cao Pi Tang.jpg", "page": "https://commons.wikimedia.org/wiki/File:Cao_Pi_Tang.jpg", "license": "Public domain", "artist": "Yan Li-pen"}}, "caozhi": {"title": "曹植", "revid": 93975973, "date": "2026-08-21", "brief": "曹植（192年—232年12月27日），字子建，沛国谯县（今安徽亳州）人，出生于东汉鄄城（今山东省菏泽市鄄城县），曹操与卞氏嫡出之第三子，三国时期曹魏的著名诗人和文学家。", "img": {"src": "portraits/caozhi.webp", "w": 240, "h": 401, "file": "File:Portrait Cao Zhi.jpg", "page": "https://commons.wikimedia.org/wiki/File:Portrait_Cao_Zhi.jpg", "license": "Public domain", "artist": "顧愷之"}}, "simayan": {"title": "司馬炎", "revid": 93770683, "date": "2026-08-04", "brief": "晋武帝司马炎（236年—290年5月16日），字安世，河内郡温县（今河南焦作温县）人。三国魏国权臣司马懿之孙，晋王司马昭长子，晋朝（西晋）开国皇帝，在位二十五年。", "img": {"src": "portraits/simayan.webp", "w": 240, "h": 315, "file": "File:Jin Wu Di.jpg", "page": "https://commons.wikimedia.org/wiki/File:Jin_Wu_Di.jpg", "license": "Public domain", "artist": "Yan Li-pen"}}, "zuti": {"title": "祖逖", "revid": 94498887, "date": "2026-09-22", "brief": "祖逖（266年—321年），字士稚，范阳郡逎县（今河北省保定市涞水县）人，东晋初期北伐将领。成语“闻鸡起舞”讲的就是他和刘琨的故事。", "img": {"src": "portraits/zuti.webp", "w": 240, "h": 348, "file": "File:Zu Ti(繡像三國演義續編).jpg", "page": "https://commons.wikimedia.org/wiki/File:Zu_Ti(%E7%B9%A1%E5%83%8F%E4%B8%89%E5%9C%8B%E6%BC%94%E7%BE%A9%E7%BA%8C%E7%B7%A8).jpg", "license": "Public domain", "artist": "金人瑞. 繡像三國演義續編 :8卷. 上海 : 廣百宋齋, 光緖19年[1893]."}}, "xiean": {"title": "谢安", "revid": 91973080, "date": "2026-03-21", "brief": "谢安（320年—385年10月12日），字安石，陈郡阳夏（今河南省太康县）人，东晋政治家、军事家。", "img": {"src": "portraits/xiean.webp", "w": 240, "h": 332, "file": "File:晋太保建昌公谢安.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E6%99%8B%E5%A4%AA%E4%BF%9D%E5%BB%BA%E6%98%8C%E5%85%AC%E8%B0%A2%E5%AE%89.jpg", "license": "Public domain", "artist": "Unknown author"}}, "taoyuanming": {"title": "陶渊明", "revid": 94766937, "date": "2026-10-05", "brief": "陶渊明（约365年—427年），一说名陶潜，字元亮，号五柳先生，友人私谥靖节先生，寻阳郡柴桑县人，中国东晋至南朝宋时期士大夫与诗人。", "img": {"src": "portraits/taoyuanming.webp", "w": 240, "h": 390, "file": "File:Tao Qian.jpg", "page": "https://commons.wikimedia.org/wiki/File:Tao_Qian.jpg", "license": "Public domain", "artist": "佚名"}}, "xiaowendi": {"title": "魏孝文帝", "revid": 92388754, "date": "2026-04-23", "brief": "魏孝文帝元宏（467年10月13日—499年4月26日），本姓拓跋氏，是北魏献文帝拓跋弘的长子，北魏第七位皇帝（471年9月20日—499年4月26日在位），后改姓“元氏”，在…", "img": {"src": "portraits/xiaowendi.webp", "w": 240, "h": 175, "file": "File:Emperor Xiaowen of Northern Wei.jpg", "page": "https://commons.wikimedia.org/wiki/File:Emperor_Xiaowen_of_Northern_Wei.jpg", "license": "Public domain", "artist": "Original uploader was Jason22 at zh.wikipedia"}}, "liuyu": {"title": "刘裕", "revid": 93808887, "date": "2026-08-08", "brief": "宋武帝刘裕（363年4月16日—422年6月26日），字德舆，小字寄奴，彭城郡彭城县绥舆里（今安徽省萧县）人，汉族人，东晋末年至南北朝初期的军事家、政治家，南北朝时期刘宋的开国…", "img": {"src": "portraits/liuyu.webp", "w": 240, "h": 272, "file": "File:Liu Yu (Song Wudi).jpg", "page": "https://commons.wikimedia.org/wiki/File:Liu_Yu_(Song_Wudi).jpg", "license": "Public domain", "artist": "Unknown author"}}, "yangguang": {"title": "隋炀帝", "revid": 94547079, "date": "2026-09-25", "brief": "隋炀帝杨广（569年—618年4月11日），又名英，小字阿𡡉，隋文帝杨坚和文献皇后独孤伽罗的次子，唐高祖的表弟，是隋朝第二位皇帝。唐高祖李渊谥杨广为炀帝；", "img": {"src": "portraits/yangguang.webp", "w": 240, "h": 376, "file": "File:Sui Yangdi Tang.jpg", "page": "https://commons.wikimedia.org/wiki/File:Sui_Yangdi_Tang.jpg", "license": "Public domain", "artist": "Yan Liben"}}, "fangxuanling": {"title": "房玄龄", "revid": 93067106, "date": "2026-06-14", "brief": "房玄龄（579年—648年8月18日），名乔，字玄龄，以字行，其神道碑则作名玄龄。清朝为避圣祖讳，又作房元龄。", "img": {"src": "portraits/fangxuanling.webp", "w": 240, "h": 336, "file": "File:房玄龄.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E6%88%BF%E7%8E%84%E9%BE%84.jpg", "license": "Public domain", "artist": "Unknown author"}}, "weizheng": {"title": "魏徵", "revid": 94032438, "date": "2026-08-24", "brief": "魏徵（zhēng）（580年—643年1月17日），字玄成，相州内黄县（今河南省安阳市内黄县）人，祖籍钜鹿郡下曲阳县（今河北省晋州市），隋唐政治家，思想家，文学家和史学家，曾任…", "img": {"src": "portraits/weizheng.webp", "w": 240, "h": 328, "file": "File:魏徵.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E9%AD%8F%E5%BE%B5.jpg", "license": "Public domain", "artist": "Unknown author"}}, "direnjie": {"title": "狄仁杰", "revid": 93965574, "date": "2026-08-20", "brief": "狄仁杰（630年—704年），字怀英，并州太原县（今山西省太原市）人，祖籍冯翊郡高陆县（今陕西省西安市高陵区）。为唐朝、武周时的著名宰相。", "img": {"src": "portraits/direnjie.webp", "w": 240, "h": 337, "file": "File:狄仁杰.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E7%8B%84%E4%BB%81%E6%9D%B0.jpg", "license": "Public domain", "artist": "Unknown author"}}, "guoziyi": {"title": "郭子仪", "revid": 94580939, "date": "2026-09-26", "brief": "郭子仪（697年—781年7月9日），华州郑县（今陕西渭南市华州区）人，祖籍并州太原，唐代政治家、军事家、名将。", "img": {"src": "portraits/guoziyi.webp", "w": 240, "h": 333, "file": "File:唐尚父汾阳忠武王像.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E5%94%90%E5%B0%9A%E7%88%B6%E6%B1%BE%E9%98%B3%E5%BF%A0%E6%AD%A6%E7%8E%8B%E5%83%8F.jpg", "license": "Public domain", "artist": "Unknown author"}}, "dufu": {"title": "杜甫", "revid": 94392366, "date": "2026-09-16", "brief": "杜甫（712年－770年），字子美，自号少陵野老，河南府巩县（今河南省巩义市人），祖籍京兆郡杜陵县（今陕西省西安市长安区），唐朝诗人。", "img": {"src": "portraits/dufu.webp", "w": 240, "h": 332, "file": "File:Dufu.jpg", "page": "https://commons.wikimedia.org/wiki/File:Dufu.jpg", "license": "Public domain", "artist": "Unknown author"}}, "baijuyi": {"title": "白居易", "revid": 94256115, "date": "2026-09-09", "brief": "白居易（772年2月28日—846年9月8日），字乐天，晚号香山居士、醉吟先生，在诗界有广大教化主的称号。", "img": {"src": "portraits/baijuyi.webp", "w": 240, "h": 338, "file": "File:唐名臣像-21-白樂天.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E5%94%90%E5%90%8D%E8%87%A3%E5%83%8F-21-%E7%99%BD%E6%A8%82%E5%A4%A9.jpg", "license": "Public domain", "artist": "Unknown author"}}, "hanyu": {"title": "韩愈", "revid": 94760424, "date": "2026-10-04", "brief": "韩愈（768年—824年12月25日），字退之，河南府河阳县（今河南省孟州市）人，自称郡望昌黎，世称韩昌黎；晚年任吏部侍郎，又称韩吏部。", "img": {"src": "portraits/hanyu.webp", "w": 240, "h": 345, "file": "File:韩愈.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E9%9F%A9%E6%84%88.jpg", "license": "Public domain", "artist": "Unknown author"}}, "liuzongyuan": {"title": "柳宗元", "revid": 94278660, "date": "2026-09-10", "brief": "柳宗元（773年—819年11月28日），字子厚，蒲州解县人，世称柳河东、河东先生，因官终柳州刺史，又称柳柳州。唐代中期士大夫、文学家与思想家，古文运动倡导者。", "img": {"src": "portraits/liuzongyuan.webp", "w": 240, "h": 293, "file": "File:柳宗元肖像.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E6%9F%B3%E5%AE%97%E5%85%83%E8%82%96%E5%83%8F.jpg", "license": "Public domain", "artist": "UnknownUnknown ,清人繪"}}, "licunxu": {"title": "李存勖", "revid": 93808966, "date": "2026-08-08", "brief": "唐庄宗李存勖（xù）（885年12月2日—926年5月15日），山西应县人，沙陀族，本姓朱邪，因其父是河东节度使李克用受唐懿宗赐姓而改姓李，讳存勖，亦作存勗（xù），唐光启元年…", "img": {"src": "portraits/licunxu.webp", "w": 240, "h": 507, "file": "File:Zhuangzong of Later Tang.jpg", "page": "https://commons.wikimedia.org/wiki/File:Zhuangzong_of_Later_Tang.jpg", "license": "Public domain", "artist": "Unknown artist"}}, "fanzhongyan": {"title": "范仲淹", "revid": 91968574, "date": "2026-03-20", "brief": "范仲淹（989年10月1日—1052年6月19日），字希文，好弹琴，尤其《履霜》一曲，人称范履霜，苏州吴县（今江苏省苏州市）人，北宋政治家、文学家、军事家、教育家。谥文正。", "img": {"src": "portraits/fanzhongyan.webp", "w": 240, "h": 303, "file": "File:Fan Zhongyan.jpg", "page": "https://commons.wikimedia.org/wiki/File:Fan_Zhongyan.jpg", "license": "Public domain", "artist": "佚名"}}, "ouyangxiu": {"title": "欧阳修", "revid": 92634057, "date": "2026-05-12", "brief": "欧阳脩（1007年8月6日—1072年9月22日），名一作修，字永叔，号醉翁、晚号六一居士，籍贯吉州庐陵县（今江西省吉安市），生于绵州（今四川绵阳），北宋文学家、史学家、政治家…", "img": {"src": "portraits/ouyangxiu.webp", "w": 240, "h": 316, "file": "File:宋参政欧阳文忠公修.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E5%AE%8B%E5%8F%82%E6%94%BF%E6%AC%A7%E9%98%B3%E6%96%87%E5%BF%A0%E5%85%AC%E4%BF%AE.jpg", "license": "Public domain", "artist": "Unknown author"}}, "simaguang": {"title": "司马光", "revid": 91973073, "date": "2026-03-21", "brief": "司马光（1019年11月17日—1086年10月11日），字君实，号迂叟，通称司马相公，陕州夏县涑水乡（今山西省夏县）人，出生于光州光山（今河南省信阳市光山县），北宋政治家、文…", "img": {"src": "portraits/simaguang.webp", "w": 240, "h": 329, "file": "File:宋丞相司马温公光.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E5%AE%8B%E4%B8%9E%E7%9B%B8%E5%8F%B8%E9%A9%AC%E6%B8%A9%E5%85%AC%E5%85%89.jpg", "license": "Public domain", "artist": "Unknown author"}}, "baozheng": {"title": "包拯", "revid": 92922643, "date": "2026-06-02", "brief": "包拯（999年3月5日—1062年7月3日），字希仁，庐州合肥（今安徽省合肥市肥东）人，北宋枢密副使，官至给事中，死后赠礼部尚书、谥“孝肃”。", "img": {"src": "portraits/baozheng.webp", "w": 240, "h": 470, "file": "File:Portrait of Bao Zheng (998-1061).jpg", "page": "https://commons.wikimedia.org/wiki/File:Portrait_of_Bao_Zheng_(998-1061).jpg", "license": "CC0", "artist": "佚名"}}, "shenkuo": {"title": "沈括", "revid": 92587130, "date": "2026-05-09", "brief": "沈括（1032年—1096年），字存中，晚年自号梦溪丈人、梦溪翁、岸老，本籍杭州钱塘县，自幼寄籍苏州吴县，北宋官员，官至龙图阁直学士、权三司使。", "img": {"src": "portraits/shenkuo.webp", "w": 240, "h": 220, "file": "File:Beijing Ancient Observatory 20090715-19 (cropped).jpg", "page": "https://commons.wikimedia.org/wiki/File:Beijing_Ancient_Observatory_20090715-19_(cropped).jpg", "license": "CC BY-SA 3.0", "artist": "Hans A. Rosbach"}}, "liqzhao": {"title": "李清照", "revid": 93410637, "date": "2026-07-11", "brief": "李清照（1084年3月13日—1155年5月12日），自号易安居士，别称“李三瘦”，齐州（今山东省济南市）人，北宋词人，为中国历史上著名的女词人。与辛幼安并称“济南二安”。", "img": {"src": "portraits/liqzhao.webp", "w": 240, "h": 334, "file": "File:李清照畫像.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E6%9D%8E%E6%B8%85%E7%85%A7%E7%95%AB%E5%83%8F.jpg", "license": "Public domain", "artist": "UnknownUnknown /清人摹"}}, "xinqiji": {"title": "辛棄疾", "revid": 94314035, "date": "2026-09-12", "brief": "辛弃疾（1140年5月28日—1207年10月3日），原字坦夫，后改为幼安，号稼轩居士，山东东路济南府历城县（今山东省济南市历城区）人，南宋著名军事家、政治家及文学家。", "img": {"src": "portraits/xinqiji.webp", "w": 240, "h": 180, "file": "File:The statue of Xin Qiji.JPG", "page": "https://commons.wikimedia.org/wiki/File:The_statue_of_Xin_Qiji.JPG", "license": "CC BY 3.0", "artist": "Huangdan2060"}}, "wentianxiang": {"title": "文天祥", "revid": 94246373, "date": "2026-09-08", "brief": "文天祥（1236年6月6日—1283年1月9日），初名云孙，字天祥，号浮休道人。选中贡士后，改天祥为名，字履善。", "img": {"src": "portraits/wentianxiang.webp", "w": 240, "h": 382, "file": "File:文天祥肖像.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E6%96%87%E5%A4%A9%E7%A5%A5%E8%82%96%E5%83%8F.jpg", "license": "Public domain", "artist": "Ye Yanlan"}}, "temujin": {"title": "成吉思汗", "revid": 94674594, "date": "2026-09-30", "brief": "成吉思汗（约1162年—1227年8月25日），本名铁木真，是大蒙古国的创建者，被后世元朝追尊为元太祖。", "img": {"src": "portraits/temujin.webp", "w": 240, "h": 305, "file": "File:YuanEmperorAlbumGenghisPortrait.jpg", "page": "https://commons.wikimedia.org/wiki/File:YuanEmperorAlbumGenghisPortrait.jpg", "license": "Public domain", "artist": "Unknown author"}}, "abaoji": {"title": "耶律阿保机", "revid": 94026022, "date": "2026-08-24", "brief": "耶律阿保机（872年—926年9月6日），清辑本《旧五代史》改译其名安巴坚；汉名亿，故又称耶律亿、刘亿，是大契丹国的第一位皇帝（916年3月7日－926年9月6日在位），在位1…", "img": {"src": "portraits/abaoji.webp", "w": 240, "h": 180, "file": "File:太阳湖公园 - 耶律阿保机像 - 2024-05-30 03.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E5%A4%AA%E9%98%B3%E6%B9%96%E5%85%AC%E5%9B%AD_-_%E8%80%B6%E5%BE%8B%E9%98%BF%E4%BF%9D%E6%9C%BA%E5%83%8F_-_2024-05-30_03.jpg", "license": "CC BY-SA 4.0", "artist": "瑞丽江的河水"}}, "aguda": {"title": "完颜阿骨打", "revid": 94533095, "date": "2026-09-24", "brief": "完颜阿骨打（1068年8月1日—1123年9月19日），汉名完颜旻，金朝开国皇帝（1115年1月28日—1123年9月19日在位）。", "img": {"src": "portraits/aguda.webp", "w": 240, "h": 351, "file": "File:Wanggiyan Aguda.jpg", "page": "https://commons.wikimedia.org/wiki/File:Wanggiyan_Aguda.jpg", "license": "Public domain", "artist": "Unknown author"}}, "liubo": {"title": "刘伯温", "revid": 94430030, "date": "2026-09-18", "brief": "刘伯温（1311年7月1日—1375年5月16日），名基，字伯温，以字行，浙江省青田县（今文成县）人，祖籍陕西保安（志丹），南宋抗金将领刘光世的后人。", "img": {"src": "portraits/liubo.webp", "w": 240, "h": 521, "file": "File:Liu Ji.jpg", "page": "https://commons.wikimedia.org/wiki/File:Liu_Ji.jpg", "license": "Public domain", "artist": "Kuan-Shou（官周）"}}, "hairui": {"title": "海瑞", "revid": 93167359, "date": "2026-06-22", "brief": "海瑞（1514年1月23日—1587年11月13日），字汝贤，又字国开、应麟，号刚峰，广东琼州琼山县（今海南海口）人，祖籍广州番禺，明朝政治家。嘉靖己酉举人，初任教谕，升知县。", "img": {"src": "portraits/hairui.webp", "w": 183, "h": 283, "file": "File:海青天像.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E6%B5%B7%E9%9D%92%E5%A4%A9%E5%83%8F.jpg", "license": "CC BY-SA 3.0", "artist": "Unknown author"}}, "qijiguang": {"title": "戚继光", "revid": 94065907, "date": "2026-08-27", "brief": "戚继光（1528年11月12日—1588年1月17日），字元敬，号南塘、孟诸，山东登州府人，明朝将领。", "img": {"src": "portraits/qijiguang.webp", "w": 240, "h": 445, "file": "File:Qi Jiguang Portrait.jpg", "page": "https://commons.wikimedia.org/wiki/File:Qi_Jiguang_Portrait.jpg", "license": "Public domain", "artist": "Thomas Chen"}}, "xuguangqi": {"title": "徐光启", "revid": 94746028, "date": "2026-10-04", "brief": "徐光启（1562年4月24日—1633年11月8日），字子先，号玄扈，圣名保禄（拉丁语：Paulus），南直隶松江府上海县人，明朝末年儒学、西学、天学、数学、水利、农学、军事学…", "img": {"src": "portraits/xuguangqi.webp", "w": 240, "h": 462, "file": "File:徐光啟.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E5%BE%90%E5%85%89%E5%95%9F.jpg", "license": "Public domain", "artist": "Unknown author"}}, "lishizhen": {"title": "李时珍", "revid": 91836789, "date": "2026-03-10", "brief": "李时珍（1518年7月3日—1593年），字东璧，晚号濒湖山人，湖广蕲州（今湖北省黄冈市蕲春县蕲州镇）人，籍贯福建上杭，明朝及中国历史上最著名的医学家、药学家和博物学家之一，其…", "img": {"src": "portraits/lishizhen.webp", "w": 240, "h": 180, "file": "File:Li Shizhen.JPG", "page": "https://commons.wikimedia.org/wiki/File:Li_Shizhen.JPG", "license": "CC BY-SA 1.0", "artist": "The original uploader was Snowyowls at Chinese Wikipedia."}}, "yuanchonghuan": {"title": "袁崇焕", "revid": 94493911, "date": "2026-09-22", "brief": "袁崇焕（1584年6月6日—1630年9月22日），字元素，号自如（一说字自如），广西梧州府藤县籍，广东东莞县（今属广东省东莞市）水南村（临近东江）人，据考为疍家人，明朝末年政…", "img": {"src": "portraits/yuanchonghuan.webp", "w": 240, "h": 345, "file": "File:袁崇煥(Yuanchonghuan).jpg", "page": "https://commons.wikimedia.org/wiki/File:%E8%A2%81%E5%B4%87%E7%85%A5(Yuanchonghuan).jpg", "license": "Public domain", "artist": "Unknown author"}}, "lizicheng": {"title": "李自成", "revid": 94799484, "date": "2026-10-06", "brief": "李自成（1606年9月22日—1645年5月17日），原名鸿基，陕西米脂人，世居米脂李继迁寨，明末民变领袖之一，大顺皇帝。", "img": {"src": "portraits/lizicheng.webp", "w": 240, "h": 401, "file": "File:李自成行宫 (cropped).png", "page": "https://commons.wikimedia.org/wiki/File:%E6%9D%8E%E8%87%AA%E6%88%90%E8%A1%8C%E5%AE%AB_(cropped).png", "license": "CC BY-SA 3.0", "artist": "Sunatnight"}}, "zhengchenggong": {"title": "鄭成功", "revid": 94626954, "date": "2026-09-28", "brief": "郑成功（1624年8月27日—1662年6月23日），赐姓朱名成功，原名森，字明俨、大木，幼名福松，通称郑成功，自称国姓成功，尊称国姓爷。", "img": {"src": "portraits/zhengchenggong.webp", "w": 240, "h": 160, "file": "File:安平古堡之美.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E5%AE%89%E5%B9%B3%E5%8F%A4%E5%A0%A1%E4%B9%8B%E7%BE%8E.jpg", "license": "CC BY-SA 3.0", "artist": "王崎"}}, "caoxueqin": {"title": "曹雪芹", "revid": 93700872, "date": "2026-07-30", "brief": "曹雪芹（1715年5月28日—1763年2月12日），名霑，字梦阮或芹圃，号雪芹或芹溪居士，清朝小说家、诗人、画家，民国学者胡适提出曹雪芹是中国古典名著《红楼梦》的作者。", "img": {"src": "portraits/caoxueqin.webp", "w": 240, "h": 320, "file": "File:Statue of Cao Xueqin.JPG", "page": "https://commons.wikimedia.org/wiki/File:Statue_of_Cao_Xueqin.JPG", "license": "CC BY-SA 3.0", "artist": "User:Yongxinge"}}, "zuozongtang": {"title": "左宗棠", "revid": 94257007, "date": "2026-09-09", "brief": "左宗棠（1812年11月10日—1885年9月5日），字季高，号湘上农人，署名今亮，谥文襄，湖南湘阴人，晚清重臣、湘军将领、政治家、文学家、军事家、外交家、实业家、改革家、诗人…", "img": {"src": "portraits/zuozongtang.webp", "w": 240, "h": 351, "file": "File:Zuo Zongtang 1875.jpg", "page": "https://commons.wikimedia.org/wiki/File:Zuo_Zongtang_1875.jpg", "license": "Public domain", "artist": "Boiarskii, Adolf-Nikolay Erazmovich"}}, "lihongzhang": {"title": "李鴻章", "revid": 94087335, "date": "2026-08-29", "brief": "李鸿章（1823年2月15日—1901年11月7日），训名章铜，字子黻、渐甫，号少荃、仪叟、省心，人称李中堂、李傅相。", "img": {"src": "portraits/lihongzhang.webp", "w": 240, "h": 349, "file": "File:Li Hung Chang in 1896.jpg", "page": "https://commons.wikimedia.org/wiki/File:Li_Hung_Chang_in_1896.jpg", "license": "Public domain", "artist": "Russell &amp; Sons"}}, "cixi": {"title": "慈禧太后", "revid": 94733413, "date": "2026-10-03", "brief": "慈禧太后（1835年11月29日—1908年11月15日），谥号孝钦显皇后（满语：ᡥᡳᠶᠣᠣᡧᡠᠩᡤᠠᡤᡳᠩᡤᡠᠵᡳᡳᠯᡝᡨᡠ᠋ᡥᡡᠸᠠᠩᡥᡝᠣ，穆麟德转写：hiyoošung…", "img": {"src": "portraits/cixi.webp", "w": 240, "h": 384, "file": "File:The Ci-Xi Imperial Dowager Empress (9.2).PNG", "page": "https://commons.wikimedia.org/wiki/File:The_Ci-Xi_Imperial_Dowager_Empress_(9.2).PNG", "license": "Public domain", "artist": "John Yu Shuinling"}}, "wangxizhi": {"title": "王羲之", "revid": 94272531, "date": "2026-09-10", "brief": "王羲之（303年—361年），字逸少，琅邪郡临沂县（今山东省临沂市）人，淮南太守王旷之子，官拜右军将军，人称王右军。", "img": {"src": "portraits/wangxizhi.webp", "w": 240, "h": 300, "file": "File:Portraits of Famous Men - Wang Xizhi (cropped).jpg", "page": "https://commons.wikimedia.org/wiki/File:Portraits_of_Famous_Men_-_Wang_Xizhi_(cropped).jpg", "license": "Public domain", "artist": "Unknown Chinese artist"}}, "jikang": {"title": "嵇康", "revid": 92741773, "date": "2026-05-21", "brief": "嵇（jī）康（223年—263年），字叔夜，谯郡铚（今安徽省濉溪县）人，因曾官至曹魏中散大夫，故后世又称嵇中散。三国曹魏文学家、思想家、音乐家。", "img": {"src": "portraits/jikang.webp", "w": 240, "h": 185, "file": "File:Seven Sages of the Bamboo Grove.jpg", "page": "https://commons.wikimedia.org/wiki/File:Seven_Sages_of_the_Bamboo_Grove.jpg", "license": "Public domain", "artist": "Unknown author"}}, "xielingyun": {"title": "谢灵运", "revid": 93427912, "date": "2026-07-12", "brief": "谢灵运（385年—433年），陈郡阳夏县（今河南省周口市太康县）人，南北朝诗人、官员，主要成就在于山水诗。由谢灵运始，山水诗乃成中国文学的一大流派。", "img": {"src": "portraits/xielingyun.webp", "w": 240, "h": 336, "file": "File:Southern and Northern Dynasties poet Xie Lingyun.jpg", "page": "https://commons.wikimedia.org/wiki/File:Southern_and_Northern_Dynasties_poet_Xie_Lingyun.jpg", "license": "Public domain", "artist": "Kanō Tsunenobu (1636-1713)"}}, "xuanzang": {"title": "玄奘", "revid": 94433121, "date": "2026-09-19", "brief": "玄奘（602年4月6日—664年3月7日），俗姓陈，名祎，洛州缑氏县（今河南省洛阳市偃师区南境）人，师承印度摩揭陀那烂陀寺戒贤大师，是唐朝三藏法师、中国佛教法相唯识宗奠基人，中…", "img": {"src": "portraits/xuanzang.webp", "w": 240, "h": 160, "file": "File:兴教寺塔CNSN-029-014.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E5%85%B4%E6%95%99%E5%AF%BA%E5%A1%94CNSN-029-014.jpg", "license": "CC BY-SA 4.0", "artist": "汤馥鳞"}}, "jianzhen": {"title": "鑑真", "revid": 92976785, "date": "2026-06-07", "brief": "释鉴真（688年—763年6月25日），唐朝僧人，俗姓淳于，江苏扬州江阳县人，日本律宗祖师。", "img": {"src": "portraits/jianzhen.webp", "w": 240, "h": 300, "file": "File:Ganjin Toshodai-ji.jpg", "page": "https://commons.wikimedia.org/wiki/File:Ganjin_Toshodai-ji.jpg", "license": "Public domain", "artist": "文化財協会"}}, "zhuwen": {"title": "朱温", "revid": 91768904, "date": "2026-03-05", "brief": "梁太祖朱温（852年12月5日—912年7月18日），宋州砀山（今安徽省砀山县）人，五代时期后梁开国皇帝。本名朱温（小名朱三），唐僖宗赐名朱全忠，称帝后改名朱晃。", "img": {"src": "portraits/zhuwen.webp", "w": 240, "h": 268, "file": "File:Zhu Wen (Liang Taizu).jpg", "page": "https://commons.wikimedia.org/wiki/File:Zhu_Wen_(Liang_Taizu).jpg", "license": "Public domain", "artist": "Unknown author"}}, "chairong": {"title": "柴荣", "revid": 93809020, "date": "2026-08-08", "brief": "后周世宗郭荣（921年10月27日—959年7月27日），本姓柴，故也习称柴荣，是五代时期后周第二位皇帝，于954年2月26日－959年7月27日在位，在位6年，庙号世宗，谥号…", "img": {"src": "portraits/chairong.webp", "w": 240, "h": 263, "file": "File:Chai Rong (Zhou Shizong).jpg", "page": "https://commons.wikimedia.org/wiki/File:Chai_Rong_(Zhou_Shizong).jpg", "license": "Public domain", "artist": "Unknown author"}}, "liyu": {"title": "李煜", "revid": 94518585, "date": "2026-09-23", "brief": "李煜（937年8月15日—978年8月15日），原名从嘉，后改名煜，字重光，号锺山隐士、钟峰隐者、白莲居士、莲峰居士等，为南唐末代国主，史称李后主。", "img": {"src": "portraits/liyu.webp", "w": 240, "h": 358, "file": "File:Li Yu scth.jpg", "page": "https://commons.wikimedia.org/wiki/File:Li_Yu_scth.jpg", "license": "Public domain", "artist": "Wang Qi (1529 - 1612)"}}, "fengdao": {"title": "馮道", "revid": 94861754, "date": "2026-10-08", "brief": "冯道（882年—954年5月21日），字可道，号长乐老，瀛州景城（今河北省沧县景城村）人。生于唐僖宗中和二年（882年），卒于后周显德元年（954年）。", "img": {"src": "portraits/fengdao.webp", "w": 240, "h": 320, "file": "File:Feng Dao, WuShuangPu (1694, 1996).jpg", "page": "https://commons.wikimedia.org/wiki/File:Feng_Dao,_WuShuangPu_(1694,_1996).jpg", "license": "Public domain", "artist": "Jin Guliang (original 1694)"}}, "xiaochuo": {"title": "萧绰", "revid": 94429313, "date": "2026-09-18", "brief": "萧绰（953年—1009年），字燕燕，中国古代辽朝皇后。萧绰即是在戏剧舞台上为后人所熟知的萧太后，辽景宗耶律贤的皇后、辽“四朝老臣”北府宰相萧思温的第三女，历史上是辽朝非常有才…", "img": {"src": "portraits/xiaochuo.webp", "w": 220, "h": 290, "file": "File:Empress Dowager Xiao 1892.jpg", "page": "https://commons.wikimedia.org/wiki/File:Empress_Dowager_Xiao_1892.jpg", "license": "Public domain", "artist": "熊大木"}}, "liyuanhao": {"title": "李元昊", "revid": 94735965, "date": "2026-10-03", "brief": "李元昊（1003年6月7日—1048年1月19日），党项名嵬名曩霄，即夏景宗，是西夏的建立者及首位皇帝，1032年至1048年统治党项政权，1038年至1048年在皇帝位。"}, "wanyanliang": {"title": "完顏亮", "revid": 94509095, "date": "2026-09-23", "brief": "完颜亮（1122年2月24日—1161年12月15日），字元功，女真名迪古乃，金朝第四任皇帝（1150年1月9日－1161年12月15日在位）。"}, "yeluchucai": {"title": "耶律楚材", "revid": 94488589, "date": "2026-09-22", "brief": "耶律楚材（1190年7月24日—1244年6月20日），又作耶律楚才、移剌楚才、耶□楚裁，字晋卿，号湛然居士、玉泉老人。", "img": {"src": "portraits/yeluchucai.webp", "w": 240, "h": 344, "file": "File:NAJDA-290-0047 古聖賢像伝略12 (page 3 耶律楚材 crop).jpg", "page": "https://commons.wikimedia.org/wiki/File:NAJDA-290-0047_%E5%8F%A4%E8%81%96%E8%B3%A2%E5%83%8F%E4%BC%9D%E7%95%A512_(page_3_%E8%80%B6%E5%BE%8B%E6%A5%9A%E6%9D%90_crop).jpg", "license": "Public domain", "artist": "著者:顧沅（清）"}}, "guoshoujing": {"title": "郭守敬", "revid": 94259015, "date": "2026-09-09", "brief": "郭守敬（1231年—1316年），字若思，邢台人，元朝天文学家、数学家和水利学家。", "img": {"src": "portraits/guoshoujing.webp", "w": 240, "h": 320, "file": "File:Guo Shoujing-beijing.JPG", "page": "https://commons.wikimedia.org/wiki/File:Guo_Shoujing-beijing.JPG", "license": "CC BY 2.5", "artist": "Shizhao"}}, "zhaomengfu": {"title": "趙孟頫", "revid": 92675012, "date": "2026-05-16", "brief": "赵孟𫖯（1254年10月22日—1322年7月30日），字子昂，号松雪道人，别号鸥波、水精宫道人，中年曾署名孟俯。两浙西路安吉州乌程（今浙江省湖州市吴兴区）人。", "img": {"src": "portraits/zhaomengfu.webp", "w": 240, "h": 332, "file": "File:趙魏公小像.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E8%B6%99%E9%AD%8F%E5%85%AC%E5%B0%8F%E5%83%8F.jpg", "license": "Public domain", "artist": "楊叔謙繪 (Yang Shuqian)"}}, "huangdaopo": {"title": "黃道婆", "revid": 94821412, "date": "2026-10-07", "brief": "黄道婆（1245年—1330年），又称黄婆、黄母，松江府华亭县乌泥泾（今上海市徐汇区华泾镇）人，生活在宋末元初，中国古代的女性棉纺织家、技术改革家。"}, "xuheng": {"title": "许衡", "revid": 93277228, "date": "2026-07-01", "brief": "许衡（1209年5月8日—1281年3月23日），字仲平，又称鲁斋先生，怀州河内（今河南沁阳）人，元代理学家、教育家。儿子许师敬。", "img": {"src": "portraits/xuheng.webp", "w": 240, "h": 330, "file": "File:至聖先賢半身像 冊-120-許衡.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E8%87%B3%E8%81%96%E5%85%88%E8%B3%A2%E5%8D%8A%E8%BA%AB%E5%83%8F_%E5%86%8A-120-%E8%A8%B1%E8%A1%A1.jpg", "license": "Public domain", "artist": "AnonymousUnknown author"}}, "yuqian": {"title": "于谦", "revid": 94661856, "date": "2026-09-30", "brief": "于谦（1398年—1457年2月16日），字廷益，号节庵，谥忠肃，明朝大臣，浙江杭州府钱塘县（今浙江省杭州市）人。官至兵部尚书、太子太傅。", "img": {"src": "portraits/yuqian.webp", "w": 240, "h": 286, "file": "File:Yu Qian by Gu Jianlong.jpg", "page": "https://commons.wikimedia.org/wiki/File:Yu_Qian_by_Gu_Jianlong.jpg", "license": "Public domain", "artist": "清 顧見龍 繪"}}, "guyanwu": {"title": "顾炎武", "revid": 94769747, "date": "2026-10-05", "brief": "顾炎武（1613年7月15日—1682年2月15日），原名绛，字宁人。明亡后，改名炎武，亦曾化名蒋山佣。", "img": {"src": "portraits/guyanwu.webp", "w": 240, "h": 336, "file": "File:Gu yanwu.jpg", "page": "https://commons.wikimedia.org/wiki/File:Gu_yanwu.jpg", "license": "Public domain", "artist": "葉衍蘭輯，黃小泉摹繪，"}}, "sunzhongshan": {"title": "孫中山", "revid": 94535291, "date": "2026-09-24", "brief": "孙中山（1866年11月12日—1925年3月12日），读书时取名文，字载之，谱名德明，幼名帝象，1886年改号逸仙，1897年化名中山樵。广东香山（今中山市）翠亨乡人。", "img": {"src": "portraits/sunzhongshan.webp", "w": 240, "h": 315, "file": "File:孙中山肖像.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E5%AD%99%E4%B8%AD%E5%B1%B1%E8%82%96%E5%83%8F.jpg", "license": "Public domain", "artist": "上海波尔照相馆"}}, "huangxing": {"title": "黄兴", "revid": 94447001, "date": "2026-09-19", "brief": "黄兴（1874年10月25日—1916年10月31日），原名轸，字廑午。后改名兴，字克强，湖南长沙人，中国近代民主革命家。", "img": {"src": "portraits/huangxing.webp", "w": 240, "h": 320, "file": "File:HWANG HSING, GEN. GENERAL LCCN2016858954 (closeup, 3to4).jpg", "page": "https://commons.wikimedia.org/wiki/File:HWANG_HSING,_GEN._GENERAL_LCCN2016858954_(closeup,_3to4).jpg", "license": "Public domain", "artist": "Harris &amp; Ewing, photographer"}}, "qiujin": {"title": "秋瑾", "revid": 94586671, "date": "2026-09-26", "brief": "秋瑾（1875年11月8日—1907年7月15日），初名闺瑾，乳名玉姑，字璿卿，号旦吾，留学日本后改名瑾，号（或作别号）竞雄，自称鉴湖女侠，笔名秋千、汉侠女儿，曾用笔名白萍。", "img": {"src": "portraits/qiujin.webp", "w": 240, "h": 343, "file": "File:Qiu jin.jpg", "page": "https://commons.wikimedia.org/wiki/File:Qiu_jin.jpg", "license": "Public domain", "artist": "Unknown, photographed in Qing Dynasty china"}}, "liangqichao": {"title": "梁启超", "revid": 94060916, "date": "2026-08-27", "brief": "梁启超（1873年2月23日—1929年1月19日），署名作梁𠷠超，字卓如、宏猷、任甫，别号任公、饮冰室主人，广东省广州府新会县潮居都茶坑乡人，人称梁新会。", "img": {"src": "portraits/liangqichao.webp", "w": 240, "h": 351, "file": "File:MinistroDeJusticiaLiangQichao.jpg", "page": "https://commons.wikimedia.org/wiki/File:MinistroDeJusticiaLiangQichao.jpg", "license": "Public domain", "artist": "Rowanwindwhistler"}}, "kangyouwei": {"title": "康有为", "revid": 94739570, "date": "2026-10-03", "brief": "康有为（1858年3月19日—1927年3月31日），原名祖诒，字广厦，号长素，又号明夷、更生、西樵山人、游存叟、天游化人，广东省广州府南海县丹灶苏村人，人称康南海，清末维新变…", "img": {"src": "portraits/kangyouwei.webp", "w": 240, "h": 274, "file": "File:Kang Yu-wei cph.3a36142.jpg", "page": "https://commons.wikimedia.org/wiki/File:Kang_Yu-wei_cph.3a36142.jpg", "license": "Public domain", "artist": "Elmer Chickering"}}, "yanfu": {"title": "嚴復", "revid": 94603249, "date": "2026-09-27", "brief": "严复（1854年1月8日—1921年10月27日），乳名体乾，初名传初，改名宗光，字又陵，后名复，字几道，晚号愈壄老人，福建省福州府侯官县人，祖籍河南固始。", "img": {"src": "portraits/yanfu.webp", "w": 240, "h": 320, "file": "File:严复.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E4%B8%A5%E5%A4%8D.jpg", "license": "Public domain", "artist": "Unknown author"}}, "caiyuanpei": {"title": "蔡元培", "revid": 94354846, "date": "2026-09-14", "brief": "蔡元培（1868年1月11日—1940年3月5日），字仲申，又字鹤卿、民友、孑民，号隺庼，小名宜哥，小字意可，乳名阿培，并曾化名蔡振、周子馀，男，浙江绍兴府山阴县（今绍兴市）人…", "img": {"src": "portraits/caiyuanpei.webp", "w": 240, "h": 320, "file": "File:Cai Yuanpei (Cropped).jpg", "page": "https://commons.wikimedia.org/wiki/File:Cai_Yuanpei_(Cropped).jpg", "license": "Public domain", "artist": "The Library of Congress"}}, "hushi": {"title": "胡適", "revid": 94628340, "date": "2026-09-28", "brief": "胡适（1891年12月17日—1962年2月24日），原名嗣穈，学名洪骍，又改名适，字适之。用过的笔名有：希彊、自胜生、铁儿、冬心、臧晖之主人、臧晖等。", "img": {"src": "portraits/hushi.webp", "w": 240, "h": 315, "file": "File:Hu Shih 1960 color.jpg", "page": "https://commons.wikimedia.org/wiki/File:Hu_Shih_1960_color.jpg", "license": "Public domain", "artist": "Unknown author"}}, "chenduxiu": {"title": "陈独秀", "revid": 94610687, "date": "2026-09-27", "brief": "陈独秀（1879年10月9日—1942年5月27日），谱名庆同，字仲甫，号实庵，1914年始用笔名独秀，安徽怀宁人，中国近现代思想家、政治家、革命家。", "img": {"src": "portraits/chenduxiu.webp", "w": 240, "h": 335, "file": "File:Chen Duxiu4.jpg", "page": "https://commons.wikimedia.org/wiki/File:Chen_Duxiu4.jpg", "license": "Public domain", "artist": "Unknown author"}}, "lidazhao": {"title": "李大钊", "revid": 94441829, "date": "2026-09-19", "brief": "李大钊（1889年10月29日—1927年4月28日），字守常，男，直隶省乐亭县（今属河北省唐山市）人。中国最早的马克思主义者之一，中国共产党早期领导人之一。", "img": {"src": "portraits/lidazhao.webp", "w": 240, "h": 320, "file": "File:1930 Li Dazhao Chinese comintern.jpg", "page": "https://commons.wikimedia.org/wiki/File:1930_Li_Dazhao_Chinese_comintern.jpg", "license": "Public domain", "artist": "Unknown author"}}, "songqingling": {"title": "宋庆龄", "revid": 94712943, "date": "2026-10-02", "brief": "宋庆龄（曾用英文名Rosamonde；1893年1月27日—1981年5月29日），曾用名宋庆林、宋庆琳，20世纪中国政治人物、社会活动家，中华人民共和国正国级领导人，孙中山遗…", "img": {"src": "portraits/songqingling.webp", "w": 240, "h": 367, "file": "File:Soong Ching-ling.jpg", "page": "https://commons.wikimedia.org/wiki/File:Soong_Ching-ling.jpg", "license": "Public domain", "artist": "Unknown author"}}, "linhuiyin": {"title": "林徽因", "revid": 93196521, "date": "2026-06-25", "brief": "林徽因（1904年6月10日—1955年4月1日），女，本名林徽音，所用英文名为PhyllisWheiYinLin，籍贯福建省福州府闽县，生于浙江杭州，中国近现代建筑学家、作家…", "img": {"src": "portraits/linhuiyin.webp", "w": 240, "h": 382, "file": "File:Lin Huiyin portrait.jpg", "page": "https://commons.wikimedia.org/wiki/File:Lin_Huiyin_portrait.jpg", "license": "Public domain", "artist": "Unknown author"}}, "meilanfang": {"title": "梅兰芳", "revid": 94299256, "date": "2026-09-11", "brief": "梅兰芳（1894年10月22日—1961年8月8日），名澜，又名鹤鸣，小名裙子、群子，字畹华，别署缀玉轩主人，中国近代京剧表演艺术家，祖籍江苏泰州，生于北京，工旦行，因其精湛演…", "img": {"src": "portraits/meilanfang.webp", "w": 240, "h": 345, "file": "File:梅兰芳.png", "page": "https://commons.wikimedia.org/wiki/File:%E6%A2%85%E5%85%B0%E8%8A%B3.png", "license": "Public domain", "artist": "Unknown author"}}, "dengxiaoping": {"title": "邓小平", "revid": 94822060, "date": "2026-10-07", "brief": "邓小平（1904年8月22日—1997年2月19日），原名先圣，学名希贤，1927年正式改名为小平，曾用名邓斌，男，四川广安人，是中国共产党和中华人民共和国政治人物，原正国级领…", "img": {"src": "portraits/dengxiaoping.webp", "w": 240, "h": 320, "file": "File:Deng Xiaoping at the arrival ceremony for the Vice Premier of China (cropped).jpg", "page": "https://commons.wikimedia.org/wiki/File:Deng_Xiaoping_at_the_arrival_ceremony_for_the_Vice_Premier_of_China_(cropped).jpg", "license": "Public domain", "artist": "Unknown author"}}, "zhude": {"title": "朱德", "revid": 94697656, "date": "2026-10-02", "brief": "朱德（1886年12月1日—1976年7月6日），原名朱代珍，曾用名建德，字玉阶，四川仪陇人，中国共产党和中华人民共和国政治人物，中华人民共和国元帅，原正国级领导人，为中国人民…", "img": {"src": "portraits/zhude.webp", "w": 240, "h": 317, "file": "File:Zhu De, Commander of PLA.jpg", "page": "https://commons.wikimedia.org/wiki/File:Zhu_De,_Commander_of_PLA.jpg", "license": "Public domain", "artist": "anonymous (Gov)"}}, "qianxuesen": {"title": "钱学森", "revid": 94644003, "date": "2026-09-29", "brief": "钱学森（1911年12月11日—2009年10月31日），浙江仁和（今杭州市）人，生于上海，中国共产党、中华人民共和国政治人物，原副国级领导人。", "img": {"src": "portraits/qianxuesen.webp", "w": 240, "h": 338, "file": "File:歸國後的錢學森.png", "page": "https://commons.wikimedia.org/wiki/File:%E6%AD%B8%E5%9C%8B%E5%BE%8C%E7%9A%84%E9%8C%A2%E5%AD%B8%E6%A3%AE.png", "license": "Public domain", "artist": "Unknown author"}}, "dengjiaxian": {"title": "邓稼先", "revid": 94709715, "date": "2026-10-02", "brief": "邓稼先（1924年6月25日—1986年7月29日），安徽怀宁人，中国理论物理学家，核物理学家，中国科学院学部委员，第12届中共中央委员、九三学社委员。", "img": {"src": "portraits/dengjiaxian.webp", "w": 240, "h": 360, "file": "File:Deng Jiaxian 1949.jpg", "page": "https://commons.wikimedia.org/wiki/File:Deng_Jiaxian_1949.jpg", "license": "Public domain", "artist": "Unknown author"}}, "yuanlongping": {"title": "袁隆平", "revid": 93294245, "date": "2026-07-02", "brief": "袁隆平（1930年9月7日—2021年5月22日），汉族，江西德安人，中国杂交水稻育种专家，中国工程院院士和美国科学院外籍院士，于1960年代至1970年代对杂交水稻品种的研究…", "img": {"src": "portraits/yuanlongping.webp", "w": 240, "h": 320, "file": "File:Yuan Longping at news conference (cropped).png", "page": "https://commons.wikimedia.org/wiki/File:Yuan_Longping_at_news_conference_(cropped).png", "license": "CC BY 3.0", "artist": "China News Service"}}, "hualuogeng": {"title": "华罗庚", "revid": 93827407, "date": "2026-08-09", "brief": "华罗庚（1910年11月12日—1985年6月12日），男，江苏金坛人，中国现代数学家，中国科学院院士，美国国家科学院外籍院士，全国政协前副主席，全国人大常委会前委员；", "img": {"src": "portraits/hualuogeng.webp", "w": 240, "h": 284, "file": "File:Hua Luogeng 1956.jpg", "page": "https://commons.wikimedia.org/wiki/File:Hua_Luogeng_1956.jpg", "license": "Public domain", "artist": "牛畏予"}}, "qiansanqiang": {"title": "錢三強", "revid": 93197267, "date": "2026-06-25", "brief": "钱三强（1913年10月16日—1992年6月28日），原名钱秉穹，男，浙江湖州人，中国原子核物理学家，中华人民共和国核科学的主要奠基人和核工业早期组织领导者。", "img": {"src": "portraits/qiansanqiang.webp", "w": 240, "h": 332, "file": "File:年轻的钱三强.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E5%B9%B4%E8%BD%BB%E7%9A%84%E9%92%B1%E4%B8%89%E5%BC%BA.jpg", "license": "Public domain", "artist": "Unknown author"}}, "zhukezhen": {"title": "竺可桢", "revid": 92870494, "date": "2026-05-31", "brief": "竺可桢（1890年3月7日—1974年2月7日），字藕舫，又名绍荣、烈祖、兆熊，男，浙江绍兴人，中国气象学家、地理学家和教育家，中央研究院院士，中国科学院院士。", "img": {"src": "portraits/zhukezhen.webp", "w": 240, "h": 315, "file": "File:Zhu Kezhen 01.jpg", "page": "https://commons.wikimedia.org/wiki/File:Zhu_Kezhen_01.jpg", "license": "Public domain", "artist": "Unknown author"}}, "lisiguang": {"title": "李四光", "revid": 93201721, "date": "2026-06-25", "brief": "李四光（1889年10月26日—1971年4月29日），字仲拱，原名李仲揆，蒙古族，湖北黄冈人，近代中国地质学家、古生物学家、社会活动家、革命者与政治人物，中国地质工作与现代地…", "img": {"src": "portraits/lisiguang.webp", "w": 240, "h": 320, "file": "File:李四光委员长.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E6%9D%8E%E5%9B%9B%E5%85%89%E5%A7%94%E5%91%98%E9%95%BF.jpg", "license": "Public domain", "artist": "Unknown author"}}, "qihuangong": {"title": "齐桓公", "revid": 94408215, "date": "2026-09-17", "brief": "齐桓公（？—前643年10月7日），春秋时代齐国第十五位国君，姜姓，齐氏，名小白，齐僖公的儿子、齐襄公的弟弟。春秋五霸之首。"}, "jinwengong": {"title": "晋文公", "revid": 94414304, "date": "2026-09-17", "brief": "晋文公（前671年—前628年10月27日），姬姓，晋氏，名重（chóng）耳，晋献公之子，春秋时期著名的政治家，晋国国君，在位九年，在赵衰（赵国先祖）、狐偃、贾佗、先轸、魏武…", "img": {"src": "portraits/jinwengong.webp", "w": 175, "h": 254, "file": "File:Duke Wen of Jin (晉文公).jpg", "page": "https://commons.wikimedia.org/wiki/File:Duke_Wen_of_Jin_(%E6%99%89%E6%96%87%E5%85%AC).jpg", "license": "Public domain", "artist": "Attributed to Li Tang"}}, "wuqi": {"title": "吴起", "revid": 94427664, "date": "2026-09-18", "brief": "吴起（前440年—前381年），中国春秋末期战国初期军事家、政治家、改革家，兵家代表人物。卫国左氏（今山东省菏泽市定陶县，一说山东省菏泽市曹县东北）人。", "img": {"src": "portraits/wuqi.webp", "w": 240, "h": 316, "file": "File:Wu Qi.jpg", "page": "https://commons.wikimedia.org/wiki/File:Wu_Qi.jpg", "license": "Public domain", "artist": "Unknown author"}}, "suqin": {"title": "苏秦", "revid": 93859949, "date": "2026-08-12", "brief": "苏秦（前382年—前284年），己姓，苏氏，有苏氏之后，字季子，东周雒邑（今河南洛阳东）乘轩里人，相传为鬼谷子徒弟。战国时期纵横家和谋略官。", "img": {"src": "portraits/suqin.webp", "w": 240, "h": 357, "file": "File:苏秦.png", "page": "https://commons.wikimedia.org/wiki/File:%E8%8B%8F%E7%A7%A6.png", "license": "Public domain", "artist": "冯梦龙、蔡元放"}}, "zhangyi": {"title": "张仪", "revid": 94710594, "date": "2026-10-02", "brief": "张仪（前373年—前310年），姬姓，张氏，魏国安邑（今山西夏县）人，战国时期著名的纵横家。", "img": {"src": "portraits/zhangyi.webp", "w": 240, "h": 326, "file": "File:张仪.png", "page": "https://commons.wikimedia.org/wiki/File:%E5%BC%A0%E4%BB%AA.png", "license": "Public domain", "artist": "冯梦龙、蔡元放"}}, "lisi": {"title": "李斯", "revid": 94651251, "date": "2026-09-29", "brief": "李斯（？—前208年），楚国上蔡（今河南省上蔡县西南方）人，秦朝政治家、文学家和书法家。李斯曾任秦朝丞相，一说左丞相，司马迁著《史记》，为李斯立《李斯列传》。或说字通古。"}, "wangmang": {"title": "王莽", "revid": 94870166, "date": "2026-10-09", "brief": "王莽（前45年—23年10月6日），字巨君，魏郡元城贵乡（今河北邯郸大名县东）人，篡夺汉朝自立，不被承认的僭主，是西汉末年政治人物、外戚及权臣。", "img": {"src": "portraits/wangmang.webp", "w": 240, "h": 346, "file": "File:WUL-he21 01467 新鐫繪像東西漢全傳 01 (王莽).jpg", "page": "https://commons.wikimedia.org/wiki/File:WUL-he21_01467_%E6%96%B0%E9%90%AB%E7%B9%AA%E5%83%8F%E6%9D%B1%E8%A5%BF%E6%BC%A2%E5%85%A8%E5%82%B3_01_(%E7%8E%8B%E8%8E%BD).jpg", "license": "Public domain", "artist": "鍾 惺, 1574-1624"}}, "liguang": {"title": "李广", "revid": 93277369, "date": "2026-07-01", "brief": "李广（前187年至前179年期间—前119年），陇西成纪人，西汉时武将。一生与匈奴交战四十余年，大小七十余战，匈奴人畏其英勇，称之为“飞将军”。", "img": {"src": "portraits/liguang.webp", "w": 240, "h": 351, "file": "File:冥山射虎.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E5%86%A5%E5%B1%B1%E5%B0%84%E8%99%8E.jpg", "license": "Public domain", "artist": "Ma Tai (馬駘; 1885-1937)"}}, "bangu": {"title": "班固", "revid": 89378831, "date": "2025-10-03", "brief": "班固（32年—92年），字孟坚，扶风安陵（今陕西咸阳）人，东汉历史学家，《汉书》作者。东汉史学家班彪之长子。", "img": {"src": "portraits/bangu.webp", "w": 240, "h": 394, "file": "File:Ban Gu.jpg", "page": "https://commons.wikimedia.org/wiki/File:Ban_Gu.jpg", "license": "Public domain", "artist": "佚名"}}, "banzhao": {"title": "班昭", "revid": 89378876, "date": "2025-10-03", "brief": "班昭（49年？—120年？），字惠班，另名姬，东汉文学家、史学家。为班彪之女，班固、班超之妹，是中国第一位女性历史学家。", "img": {"src": "portraits/banzhao.webp", "w": 240, "h": 596, "file": "File:Ban Zhao.jpg", "page": "https://commons.wikimedia.org/wiki/File:Ban_Zhao.jpg", "license": "Public domain", "artist": "佚名"}}, "zhangzhongjing": {"title": "張仲景", "revid": 94102479, "date": "2026-08-30", "brief": "张仲景（150年—219年），名机，字仲景，以字行，南阳郡涅阳县（今河南邓州市和镇平县一带）人，东汉末年医学家。汉灵帝时曾任长沙太守。", "img": {"src": "portraits/zhangzhongjing.webp", "w": 240, "h": 360, "file": "File:Chinese woodcut, Famous medical figures; Zhang Zhongjing Wellcome L0039319.jpg", "page": "https://commons.wikimedia.org/wiki/File:Chinese_woodcut,_Famous_medical_figures;_Zhang_Zhongjing_Wellcome_L0039319.jpg", "license": "CC BY 4.0", "artist": "Gan Bozong (Tang period, 618-907)"}}, "huatuo": {"title": "华佗", "revid": 94283085, "date": "2026-09-10", "brief": "华佗（145年—208年），字元化，名旉（读音同“敷”），沛国谯县（今安徽亳州市）人，东汉末年的方士、医师。华佗与董奉和张仲景被并称为“建安三神医”。", "img": {"src": "portraits/huatuo.webp", "w": 240, "h": 329, "file": "File:汉名医华佗.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E6%B1%89%E5%90%8D%E5%8C%BB%E5%8D%8E%E4%BD%97.jpg", "license": "Public domain", "artist": "Unknown author"}}, "wangdao": {"title": "王導", "revid": 94765326, "date": "2026-10-05", "brief": "王导（276年—339年9月7日），字茂弘，琅邪临沂（今山东省临沂市）人。是东晋初年权臣，历仕晋元帝、晋明帝和晋成帝三代。", "img": {"src": "portraits/wangdao.webp", "w": 240, "h": 331, "file": "File:NAJDA-290-0047 古聖賢像伝略5 (王導).jpg", "page": "https://commons.wikimedia.org/wiki/File:NAJDA-290-0047_%E5%8F%A4%E8%81%96%E8%B3%A2%E5%83%8F%E4%BC%9D%E7%95%A55_(%E7%8E%8B%E5%B0%8E).jpg", "license": "Public domain", "artist": "著者:顧沅（清）"}}, "liyuan": {"title": "李渊", "revid": 94308317, "date": "2026-09-12", "brief": "李渊（566年4月7日—635年6月25日），字叔德，唐朝开国皇帝，庙号高祖。李渊出身北周以来的关陇集团，父为隋朝唐国公李昞（一作李昺），母为独孤氏，家族与北周、隋两朝上层政治…", "img": {"src": "portraits/liyuan.webp", "w": 240, "h": 494, "file": "File:TangGaozu.jpg", "page": "https://commons.wikimedia.org/wiki/File:TangGaozu.jpg", "license": "Public domain", "artist": "Unknown author"}}, "lijing": {"title": "李靖", "revid": 93079908, "date": "2026-06-15", "brief": "李靖（571年—649年7月2日），字药师，雍州三原县（今陕西省咸阳市三原县东北）人，祖籍陇西郡狄道县（今甘肃省定西市临洮县），出自陇西李氏定著四房之一的丹杨房，隋末唐初名将…", "img": {"src": "portraits/lijing.webp", "w": 240, "h": 341, "file": "File:李靖.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E6%9D%8E%E9%9D%96.jpg", "license": "CC BY-SA 3.0", "artist": "Unknown author"}}, "changsunqueen": {"title": "长孙皇后", "revid": 93683623, "date": "2026-07-28", "brief": "长孙皇后（601年3月15日—636年7月28日），河南郡洛阳县（河南省洛阳市东）人，中国唐朝唐太宗李世民之皇后。唐朝第一个在位皇后。贞观十年去世，谥号为文德皇后。"}, "wangwei": {"title": "王维", "revid": 92824191, "date": "2026-05-28", "brief": "王维（699年—761年），字摩诘，人称摩诘居士，以官职被称为王右丞，有诗佛之称，山西太原祁县人，唐代官员、诗人兼画家。", "img": {"src": "portraits/wangwei.webp", "w": 240, "h": 294, "file": "File:Wang Wei.jpg", "page": "https://commons.wikimedia.org/wiki/File:Wang_Wei.jpg", "license": "Public domain", "artist": "佚名"}}, "zhuxi": {"title": "朱熹", "revid": 94482815, "date": "2026-09-21", "brief": "朱熹（xī）（1130年10月18日—1200年4月23日），字元晦，一字仲晦，斋号晦庵、考亭，晚称晦翁，又称紫阳先生、紫阳夫子、沧州病叟、云谷老人，行五十二，小名沋郎，小字季…", "img": {"src": "portraits/zhuxi.webp", "w": 240, "h": 320, "file": "File:朱熹画像（截取）.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E6%9C%B1%E7%86%B9%E7%94%BB%E5%83%8F%EF%BC%88%E6%88%AA%E5%8F%96%EF%BC%89.jpg", "license": "Public domain", "artist": "Unknown author"}}, "luyou": {"title": "陸游", "revid": 94370902, "date": "2026-09-15", "brief": "陆游（1125年11月13日—1210年1月26日），字务观，号放翁，越州山阴（今浙江绍兴）人，南宋诗人、词人。后人每以陆游为南宋诗人之冠。", "img": {"src": "portraits/luyou.webp", "w": 240, "h": 364, "file": "File:陸游 肖像.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E9%99%B8%E6%B8%B8_%E8%82%96%E5%83%8F.jpg", "license": "Public domain", "artist": "UnknownUnknown ,清人 繪"}}, "luxiufu": {"title": "陸秀夫", "revid": 94856006, "date": "2026-10-08", "brief": "陆秀夫（1238年11月15日—1279年3月19日），字君实，楚州盐城长建里（今江苏省盐城市建湖县）人，南宋末年政治家，与文天祥和张世杰并称为“宋末三杰”，于宋军在崖山之战失…", "img": {"src": "portraits/luxiufu.webp", "w": 240, "h": 361, "file": "File:陸秀夫.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E9%99%B8%E7%A7%80%E5%A4%AB.jpg", "license": "Public domain", "artist": "Qing Gu Yuanji"}}, "tangxianzu": {"title": "汤显祖", "revid": 93002012, "date": "2026-06-09", "brief": "汤显祖（1550年9月24日—1616年7月29日），字义仍，号海若、若士，晚号茧翁，别署清远道人，室名玉茗堂。江西临川县人。明代政治家、文学家、戏曲家、教育家。", "img": {"src": "portraits/tangxianzu.webp", "w": 240, "h": 385, "file": "File:湯顯祖.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E6%B9%AF%E9%A1%AF%E7%A5%96.jpg", "license": "Public domain", "artist": "Symane"}}, "songyingxing": {"title": "宋应星", "revid": 92733897, "date": "2026-05-20", "brief": "宋应星（1587年—约1666年），字长庚，明朝发明家。江西南昌府奉新县北乡雅溪牌坊宋家（今宋埠镇牌楼村）人，汉族江右民系。英国汉学家与历史学家李约瑟称他为“中国的狄德罗”。"}, "xuxiake": {"title": "徐霞客", "revid": 94065797, "date": "2026-08-27", "brief": "徐霞客（1587年1月5日—1641年3月8日，即万历十四年十一月廿七日－崇祯十四年正月廿七日），名弘祖，字振之，号霞客，直隶常州府江阴县人，祖籍江西南昌，是明代著名的地理学家…", "img": {"src": "portraits/xuxiake.webp", "w": 240, "h": 169, "file": "File:Travels of Xu Xiake.png", "page": "https://commons.wikimedia.org/wiki/File:Travels_of_Xu_Xiake.png", "license": "CC BY-SA 4.0", "artist": "SY"}}, "huangzongxi": {"title": "黄宗羲", "revid": 93118649, "date": "2026-06-18", "brief": "黄宗羲（1610年9月24日—1695年8月12日），字太冲，号梨洲，世称南雷先生或梨洲先生，浙江绍兴府余姚县（今浙江省余姚市）人。", "img": {"src": "portraits/huangzongxi.webp", "w": 240, "h": 333, "file": "File:Huang Zong-Xi.jpg", "page": "https://commons.wikimedia.org/wiki/File:Huang_Zong-Xi.jpg", "license": "CC BY-SA 3.0", "artist": "Drag the cane to sing the immortal (曳杖行歌意欲仙)"}}, "wangfuzhi": {"title": "王夫之", "revid": 94045716, "date": "2026-08-25", "brief": "王夫之（1619年10月7日—1692年2月18日），字而农，号姜斋、又号夕堂，或署一瓢道人、双髻外史，自署船山病叟、南岳遗民，湖广衡州府衡阳县人，明末清初儒者，思想家、哲学家…", "img": {"src": "portraits/wangfuzhi.webp", "w": 240, "h": 374, "file": "File:王夫之.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E7%8E%8B%E5%A4%AB%E4%B9%8B.jpg", "license": "Public domain", "artist": "叶公绰辑，杨鹏秋摹绘。"}}, "weiyuan": {"title": "魏源", "revid": 93770745, "date": "2026-08-04", "brief": "魏源（1794年4月23日—1857年3月26日），原名远达，字默深，一字墨生，又字汉士，号良图，湖南省邵阳县（今邵阳市隆回县）人。为晚清思想家，新思想的倡导者、林则徐的好友。", "img": {"src": "portraits/weiyuan.webp", "w": 240, "h": 361, "file": "File:Wei Yuan.png", "page": "https://commons.wikimedia.org/wiki/File:Wei_Yuan.png", "license": "Public domain", "artist": "叶衍兰"}}, "zhantianyou": {"title": "詹天佑", "revid": 93785746, "date": "2026-08-06", "brief": "詹天佑（1861年4月26日—1919年4月24日），字眷诚，号达潮，男，广东省广州府南海县（今广州市荔湾区）人，祖籍安徽省徽州府婺源县，中国首位铁路总工程师，负责修建了京张铁…", "img": {"src": "portraits/zhantianyou.webp", "w": 240, "h": 329, "file": "File:1918年詹天佑.jpg", "page": "https://commons.wikimedia.org/wiki/File:1918%E5%B9%B4%E8%A9%B9%E5%A4%A9%E4%BD%91.jpg", "license": "Public domain", "artist": "Unknown author"}}, "zhangjian": {"title": "张謇", "revid": 94275117, "date": "2026-09-10", "brief": "张謇（jiǎn）（1853年7月1日—1926年8月24日），字季直，号啬庵，生于今江苏海门，清末状元。中国近代实业家、政治家、教育家，主张“实业救国”。", "img": {"src": "portraits/zhangjian.webp", "w": 240, "h": 303, "file": "File:Zhang Jian.jpg", "page": "https://commons.wikimedia.org/wiki/File:Zhang_Jian.jpg", "license": "Public domain", "artist": "Unknown author"}}, "qibaishi": {"title": "齐白石", "revid": 94499632, "date": "2026-09-22", "brief": "齐白石（1864年1月1日—1957年9月16日），原名齐纯芝，字渭清，祖父取号兰亭，老师取名璜，字濒生，别号寄萍老人、白石山人，湖南湘潭人，国画画家。", "img": {"src": "portraits/qibaishi.webp", "w": 240, "h": 353, "file": "File:Qi Baishi (1956), by Zheng Jingkang.jpg", "page": "https://commons.wikimedia.org/wiki/File:Qi_Baishi_(1956),_by_Zheng_Jingkang.jpg", "license": "Public domain", "artist": "Zheng Jingkang"}}, "caie": {"title": "蔡锷", "revid": 94229895, "date": "2026-09-07", "brief": "蔡锷（è）（1882年12月18日—1916年11月8日），原名艮（gèn）寅（yín），字松坡，祖籍原湖南省宝庆府邵阳县（今邵阳市大祥区），出生成长于原宝庆府武冈州山门（今属…", "img": {"src": "portraits/caie.webp", "w": 240, "h": 369, "file": "File:GeneralQaoAoCampañaDeYunnan.jpg", "page": "https://commons.wikimedia.org/wiki/File:GeneralQaoAoCampa%C3%B1aDeYunnan.jpg", "license": "CC BY-SA 3.0", "artist": "Rowanwindwhistler"}}, "xubeihong": {"title": "徐悲鸿", "revid": 93578102, "date": "2026-07-21", "brief": "徐悲鸿（1895年7月19日—1953年9月26日），原名徐寿康，男，江苏宜兴人，中国现代画家、美术教育家，兼擅油画及水墨画。", "img": {"src": "portraits/xubeihong.webp", "w": 240, "h": 297, "file": "File:XuBeihong.jpg", "page": "https://commons.wikimedia.org/wiki/File:XuBeihong.jpg", "license": "Public domain", "artist": "佚名"}}, "maoyisheng": {"title": "茅以昇", "revid": 94310760, "date": "2026-09-12", "brief": "茅以昇（1896年1月9日—1989年11月12日），又作茅以升，字唐臣，男，江苏镇江人，中国近代结构工程师，桥梁工程专家与科普作家，被视为中国土力学的开拓者、中国近代桥梁事业…", "img": {"src": "portraits/maoyisheng.webp", "w": 240, "h": 320, "file": "File:茅以昇院士.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E8%8C%85%E4%BB%A5%E6%98%87%E9%99%A2%E5%A3%AB.jpg", "license": "Public domain", "artist": "Unknown author"}}, "zhougong": {"title": "周公旦", "revid": 93893190, "date": "2026-08-14", "brief": "周公旦，姬姓，周氏，名旦，谥文，又称周文公、周公。周文王第四子、周武王之弟，西周初年政治家，封于周邑，为诸侯国鲁国之祖，创“礼乐制度”。", "img": {"src": "portraits/zhougong.webp", "w": 240, "h": 374, "file": "File:Zhou gong.jpg", "page": "https://commons.wikimedia.org/wiki/File:Zhou_gong.jpg", "license": "Public domain", "artist": "Wang Qi"}}, "jiangshang": {"title": "姜太公", "revid": 94408348, "date": "2026-09-17", "brief": "太公望，姓姜，氏吕，名尚，字子牙，是周文王、周武王的军师，史册记载名字有姜尚、姜望、姜牙、姜子牙、吕尚、吕望、吕涓、吕牙，别称有姜太公、吕太公、齐太公、太公、太公望、尚父、师尚…", "img": {"src": "portraits/jiangshang.webp", "w": 240, "h": 330, "file": "File:Portrait of Jiang Ziya.jpg", "page": "https://commons.wikimedia.org/wiki/File:Portrait_of_Jiang_Ziya.jpg", "license": "Public domain", "artist": "Unknown author"}}, "yanying": {"title": "晏婴", "revid": 94748139, "date": "2026-10-04", "brief": "晏婴（前578年—前500年），字仲，谥平，习惯上多称晏平仲，亦称晏子。齐国莱地夷维人，祖籍为宋国。春秋后期外交家、思想家。", "img": {"src": "portraits/yanying.webp", "w": 240, "h": 323, "file": "File:Yan Ying.png", "page": "https://commons.wikimedia.org/wiki/File:Yan_Ying.png", "license": "Public domain", "artist": "Unknown author"}}, "sunbin": {"title": "孙膑", "revid": 94766626, "date": "2026-10-05", "brief": "孙膑（前382年—前316年），或说号伯灵，妫姓，孙氏，本名不详，战国中期军事家，兵家代表人物。", "img": {"src": "portraits/sunbin.webp", "w": 240, "h": 313, "file": "File:Sun Bin.jpg", "page": "https://commons.wikimedia.org/wiki/File:Sun_Bin.jpg", "license": "Public domain", "artist": "Unknown author"}}, "yueyi": {"title": "乐毅", "revid": 92238393, "date": "2026-04-10", "brief": "乐（yuè）毅（约前300年—约前260年），子姓，乐氏，中国战国时期燕国著名军事家，辅佐燕昭王，曾攻下齐国70余城而封昌国君，后获赵国封望诸君。", "img": {"src": "portraits/yueyi.webp", "w": 240, "h": 267, "file": "File:乐毅像（清人绘）.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E4%B9%90%E6%AF%85%E5%83%8F%EF%BC%88%E6%B8%85%E4%BA%BA%E7%BB%98%EF%BC%89.jpg", "license": "Public domain", "artist": "Unknown author"}}, "tiandan": {"title": "田單", "revid": 94706174, "date": "2026-10-02", "brief": "田单（？—？），临淄人，齐国军事家，战国时田齐宗室远房的亲属，原为齐都临淄管理市场的小吏。在即墨之战中以火牛阵破燕军，及后收复七十城。", "img": {"src": "portraits/tiandan.webp", "w": 240, "h": 263, "file": "File:田单彩像（清人绘）.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E7%94%B0%E5%8D%95%E5%BD%A9%E5%83%8F%EF%BC%88%E6%B8%85%E4%BA%BA%E7%BB%98%EF%BC%89.jpg", "license": "Public domain", "artist": "Unknown author"}}, "xinlingjun": {"title": "信陵君", "revid": 94719102, "date": "2026-10-03", "brief": "信陵君（？—前243年），姬姓，魏氏，名无忌，中国战国时代魏国人，是魏昭王的儿子，魏安釐王同父异母的弟弟，后世亦称魏公子。", "img": {"src": "portraits/xinlingjun.webp", "w": 240, "h": 323, "file": "File:NJlib-0026095-0001 東周列國志二十七卷一百八回圖二卷 (信陵君).jpg", "page": "https://commons.wikimedia.org/wiki/File:NJlib-0026095-0001_%E6%9D%B1%E5%91%A8%E5%88%97%E5%9C%8B%E5%BF%97%E4%BA%8C%E5%8D%81%E4%B8%83%E5%8D%B7%E4%B8%80%E7%99%BE%E5%85%AB%E5%9B%9E%E5%9C%96%E4%BA%8C%E5%8D%B7_(%E4%BF%A1%E9%99%B5%E5%90%9B).jpg", "license": "Public domain", "artist": "清蔡奡評點"}}, "mengchangjun": {"title": "孟尝君", "revid": 94692367, "date": "2026-10-01", "brief": "孟尝君（？—前279年），妫姓，田氏，名文，字孟，战国四公子之一，齐国的公族。其父靖郭君田婴死后，田文继位薛公于薛城（今山东滕州东南），号孟尝君，以广招宾客、食客三千闻名。", "img": {"src": "portraits/mengchangjun.webp", "w": 240, "h": 358, "file": "File:孟尝君.png", "page": "https://commons.wikimedia.org/wiki/File:%E5%AD%9F%E5%B0%9D%E5%90%9B.png", "license": "Public domain", "artist": "冯梦龙、蔡元放"}}, "zhaowulingwang": {"title": "赵武灵王", "revid": 94258960, "date": "2026-09-09", "brief": "赵武灵王（前356年—前295年），嬴姓，赵氏，名雍，中国战国中后期赵国的君主。死后谥号武灵。", "img": {"src": "portraits/zhaowulingwang.webp", "w": 240, "h": 320, "file": "File:武灵丛台 6.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E6%AD%A6%E7%81%B5%E4%B8%9B%E5%8F%B0_6.jpg", "license": "CC0", "artist": "H2v5o68z"}}, "jingke": {"title": "荆轲", "revid": 94577810, "date": "2026-09-26", "brief": "荆轲（？—前227年），战国末期卫国人，著名刺客。也称庆卿、荆卿、庆轲。受燕太子丹之托入刺秦王政，失败被杀。", "img": {"src": "portraits/jingke.webp", "w": 240, "h": 107, "file": "File:Assassination attempt on Qin Shi Huang.jpg", "page": "https://commons.wikimedia.org/wiki/File:Assassination_attempt_on_Qin_Shi_Huang.jpg", "license": "Public domain", "artist": "Unknown (2??–2??)"}}, "mengtian": {"title": "蒙恬", "revid": 91777016, "date": "2026-03-05", "brief": "蒙恬（tián）（约前250年—前210年），中国秦朝将领、书法家，祖居齐国，官至内史，祖父蒙骜和父亲蒙武皆为秦国名将。蒙恬北防匈奴多年，威震北方。"}, "fusu": {"title": "扶苏", "revid": 91634629, "date": "2026-02-22", "brief": "扶苏（—前210年），嬴姓，秦始皇长子，秦朝政治人物。秦始皇驾崩后，赵高和李斯等人矫诏谋杀扶苏，改立公子胡亥为帝，是为沙丘之变。"}, "chensheng": {"title": "陈胜", "revid": 94386382, "date": "2026-09-16", "brief": "陈胜（？—前208年），字涉，秦朝阳城（在今河南省商水县）人。秦末民变领袖。因秦法严苛，与吴广带领约九百名戍卒发动大泽乡起义，首先抗秦，在其败退时遭车夫庄贾刺杀而死，谥号楚隐王…"}, "xiangliang": {"title": "項梁", "revid": 94007309, "date": "2026-08-23", "brief": "项梁（？—前208年9月），楚国下相（今江苏省宿迁市宿城区）人，秦末起义军首领之一。楚国贵族项氏的后裔，项燕的儿子，西楚霸王项羽的叔父。"}, "yingbu": {"title": "英布", "revid": 93921439, "date": "2026-08-17", "brief": "英布（？—前195年），因受秦律被黥（拼音：qíng，注音：ㄑㄧㄥˊ），又称黥布，六县（今安徽六安）人，秦末汉初名将，项羽封其为九江王，后叛楚归汉，与韩信、彭越并称汉初三大名将…", "img": {"src": "portraits/yingbu.webp", "w": 240, "h": 346, "file": "File:WUL-he21 01467 新鐫繪像東西漢全傳 01 (英布).jpg", "page": "https://commons.wikimedia.org/wiki/File:WUL-he21_01467_%E6%96%B0%E9%90%AB%E7%B9%AA%E5%83%8F%E6%9D%B1%E8%A5%BF%E6%BC%A2%E5%85%A8%E5%82%B3_01_(%E8%8B%B1%E5%B8%83).jpg", "license": "Public domain", "artist": "鍾 惺, 1574-1624"}}, "zhouyafu": {"title": "周亚夫", "revid": 89507543, "date": "2025-10-13", "brief": "周亚夫（？—前143年），西汉沛郡丰县（今江苏省徐州市丰县）人，为太尉周勃之子。汉文帝时，曾任河内郡太守，获封条侯。", "img": {"src": "portraits/zhouyafu.webp", "w": 240, "h": 348, "file": "File:細柳式車.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E7%B4%B0%E6%9F%B3%E5%BC%8F%E8%BB%8A.jpg", "license": "Public domain", "artist": "Ma Tai (馬駘; 1885-1937)"}}, "jiayi": {"title": "贾谊", "revid": 93012786, "date": "2026-06-10", "brief": "贾谊（前200年—前168年），雒阳（今河南省洛阳市东）人，西汉政论家、思想家、文学家。由于是知名的学者，人称贾生、当过长沙王太傅，故世称贾太傅、贾长沙。", "img": {"src": "portraits/jiayi.webp", "w": 240, "h": 366, "file": "File:Jia Yi.png", "page": "https://commons.wikimedia.org/wiki/File:Jia_Yi.png", "license": "Public domain", "artist": "Unknown author"}}, "dongzhongshu": {"title": "董仲舒", "revid": 94395597, "date": "2026-09-16", "brief": "董仲舒（前2世纪—？），广川（今河北省景县）人，西汉时官员与学者，活跃于汉景帝至汉武帝时期，曾任《春秋》博士、江都国相、胶西国相。", "img": {"src": "portraits/dongzhongshu.webp", "w": 240, "h": 274, "file": "File:歷代聖賢半身像 冊 董仲舒 (Dong Zhongshu).png", "page": "https://commons.wikimedia.org/wiki/File:%E6%AD%B7%E4%BB%A3%E8%81%96%E8%B3%A2%E5%8D%8A%E8%BA%AB%E5%83%8F_%E5%86%8A_%E8%91%A3%E4%BB%B2%E8%88%92_(Dong_Zhongshu).png", "license": "CC BY 4.0", "artist": "佚名"}}, "zhangqian": {"title": "張騫", "revid": 93940856, "date": "2026-08-18", "brief": "张骞（前175年2月25日—前114年4月25日），字子文，汉中郡成固（今陕西省城固县）人，西汉旅行家、外交家、探险家，丝绸之路的开拓者。", "img": {"src": "portraits/zhangqian.webp", "w": 240, "h": 320, "file": "File:Zhangqian Statue.jpg", "page": "https://commons.wikimedia.org/wiki/File:Zhangqian_Statue.jpg", "license": "CC BY-SA 4.0", "artist": "千里走单骑"}}, "suwu": {"title": "苏武", "revid": 93065816, "date": "2026-06-14", "brief": "苏武（前140年—前60年），字子卿，京兆杜陵（今陕西西安东南）人。西汉大臣、外交家，位列麒麟阁十一功臣之末。", "img": {"src": "portraits/suwu.webp", "w": 240, "h": 361, "file": "File:Su Wu.jpg", "page": "https://commons.wikimedia.org/wiki/File:Su_Wu.jpg", "license": "Public domain", "artist": "佚名"}}, "mayuan": {"title": "马援", "revid": 94629619, "date": "2026-09-28", "brief": "马援（前14年—49年），字文渊，扶风郡茂陵（今陕西省兴平市东北）人，东汉军事家。汉光武帝时，拜为伏波将军，封新息侯，世称马伏波。", "img": {"src": "portraits/mayuan.webp", "w": 240, "h": 180, "file": "File:Tianya Haijiao 010.JPG", "page": "https://commons.wikimedia.org/wiki/File:Tianya_Haijiao_010.JPG", "license": "CC BY 3.0", "artist": "Huangdan2060"}}, "douxian": {"title": "竇憲", "revid": 88793401, "date": "2025-08-19", "brief": "窦宪（？—92年），字伯度，祖籍扶风平陵（今陕西咸阳西北）人，窦融之曾孙，祖上六代居住于凉州。东汉外戚、权臣、将领。典故“燕然勒石”就来自窦宪，凉州武力豪族的代表人物之一。"}, "wangchong": {"title": "王充", "revid": 94230532, "date": "2026-09-07", "brief": "王充（27年—约97年），字仲任，会稽郡上虞县人（今浙江省绍兴市上虞），东汉时的士人与思想家。"}, "zhengxuan": {"title": "郑玄", "revid": 93643573, "date": "2026-07-25", "brief": "郑玄（127年8月29日—200年7月），字康成，北海高密（今山东省高密市）人，东汉经学家、预言家。集两汉经学小成。曾拜大司农。《拾遗记》称郑玄为“经神”。", "img": {"src": "portraits/zhengxuan.webp", "w": 240, "h": 334, "file": "File:至聖先賢半身像 冊-100-鄭玄.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E8%87%B3%E8%81%96%E5%85%88%E8%B3%A2%E5%8D%8A%E8%BA%AB%E5%83%8F_%E5%86%8A-100-%E9%84%AD%E7%8E%84.jpg", "license": "Public domain", "artist": "AnonymousUnknown author"}}, "xunyu": {"title": "荀彧", "revid": 94623080, "date": "2026-09-28", "brief": "荀（xún）彧（yù）（163年—212年），字文若，颍川郡颍阴县（今河南省许昌市魏都区）人，朗陵侯相荀淑之孙。", "img": {"src": "portraits/xunyu.webp", "w": 240, "h": 372, "file": "File:Portrait of Xun Yu.jpg", "page": "https://commons.wikimedia.org/wiki/File:Portrait_of_Xun_Yu.jpg", "license": "Public domain", "artist": "Unknown author"}}, "guojia": {"title": "郭嘉", "revid": 94234007, "date": "2026-09-07", "brief": "郭嘉（170年—207年），字奉孝，颍川阳翟人（今河南省禹州市），初为东汉末年群雄袁绍麾下，后成为曹操麾下重要谋士，任司空府军师祭酒，封洧阳亭侯，谥号贞侯。", "img": {"src": "portraits/guojia.webp", "w": 240, "h": 489, "file": "File:GuoJia.jpg", "page": "https://commons.wikimedia.org/wiki/File:GuoJia.jpg", "license": "Public domain", "artist": "佚名"}}, "lubu": {"title": "吕布", "revid": 94559261, "date": "2026-09-25", "brief": "吕布（160年或更早—199年2月7日），字奉先，并州五原郡九原（今内蒙古自治区包头市九原区）人，东汉末年武将与军阀，被封为温侯。", "img": {"src": "portraits/lubu.webp", "w": 240, "h": 433, "file": "File:Lü Bu Portrait.jpg", "page": "https://commons.wikimedia.org/wiki/File:L%C3%BC_Bu_Portrait.jpg", "license": "Public domain", "artist": "佚名"}}, "yuanshao": {"title": "袁绍", "revid": 94232279, "date": "2026-09-07", "brief": "袁绍（？—202年6月28日），字本初，汝南郡汝阳县（今河南省商水县）人，为东汉末年割据势力之一。他出自名门望族，曾带兵进宫诛杀十常侍，后被各路诸侯推举为盟主讨伐董卓。", "img": {"src": "portraits/yuanshao.webp", "w": 240, "h": 474, "file": "File:Yuan Shao Portrait.jpg", "page": "https://commons.wikimedia.org/wiki/File:Yuan_Shao_Portrait.jpg", "license": "Public domain", "artist": "The original uploader was Plastictv at English Wikipedia."}}, "dongzhuo": {"title": "董卓", "revid": 94728515, "date": "2026-10-03", "brief": "董卓（139年？—192年5月22日），字仲颖，凉州陇西临洮（今甘肃岷县）人，东汉与羌的战争中崛起的汉军将领。董卓长期参与汉羌战争，先后跟过张奂、段颎两位汉军高级将领。", "img": {"src": "portraits/dongzhuo.webp", "w": 240, "h": 497, "file": "File:Dong Zhuo Portrait.jpg", "page": "https://commons.wikimedia.org/wiki/File:Dong_Zhuo_Portrait.jpg", "license": "Public domain", "artist": "The original uploader was Plastictv at English Wikipedia."}}, "lusu": {"title": "鲁肃", "revid": 94411965, "date": "2026-09-17", "brief": "鲁肃（172年—217年），字子敬，徐州临淮郡东城县（今安徽省定远县）人，东汉末年东吴将领、军事家、战略家、外交家、政治家，为孙权策划未来战略蓝图榻上策，在周瑜去世后接替其职务…", "img": {"src": "portraits/lusu.webp", "w": 240, "h": 466, "file": "File:LuSu.jpg", "page": "https://commons.wikimedia.org/wiki/File:LuSu.jpg", "license": "Public domain", "artist": "Unknown author"}}, "jiangwei": {"title": "姜维", "revid": 94093168, "date": "2026-08-29", "brief": "姜维（202年—264年3月3日），字伯约，凉州天水郡冀县（今甘肃省天水市甘谷县）人，三国时期蜀汉著名军事家。姜维早年仕于曹魏，任天水郡中郎、参郡军事。", "img": {"src": "portraits/jiangwei.webp", "w": 240, "h": 423, "file": "File:JiangWei.jpg", "page": "https://commons.wikimedia.org/wiki/File:JiangWei.jpg", "license": "Public domain", "artist": "Unknown author"}}, "simazhao": {"title": "司马昭", "revid": 94428628, "date": "2026-09-18", "brief": "司马昭（211年—265年9月6日），字子上（小说《三国演义》为子尚），河内郡温县（今河南省温县）人，曹魏后期政治家和军事家，晋朝奠基者。官至相国，爵至晋王。", "img": {"src": "portraits/simazhao.webp", "w": 240, "h": 304, "file": "File:SimaZhao.jpg", "page": "https://commons.wikimedia.org/wiki/File:SimaZhao.jpg", "license": "Public domain", "artist": "Unknown author"}}, "huanwen": {"title": "桓温", "revid": 94064521, "date": "2026-08-27", "brief": "桓温（312年—373年8月18日），字元子，谯国龙亢县（今安徽省怀远县）人。东晋重要将领及权臣、军事家，谯国桓氏代表人物。官至大司马、录尚书事。"}, "wangmeng": {"title": "王猛", "revid": 94798995, "date": "2026-10-06", "brief": "王猛（325年—375年），字景略，北海郡剧县（今山东潍坊市昌乐县西）人，后移家魏郡。十六国时期重要政治家、军事家，于前秦官至丞相，爵封清河武侯。", "img": {"src": "portraits/wangmeng.webp", "w": 240, "h": 190, "file": "File:任熊 人物山水册 7.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E4%BB%BB%E7%86%8A_%E4%BA%BA%E7%89%A9%E5%B1%B1%E6%B0%B4%E5%86%8C_7.jpg", "license": "Public domain", "artist": "Ren Xiong"}}, "fujian": {"title": "苻坚", "revid": 91069522, "date": "2026-01-11", "brief": "秦宣昭帝苻坚（338年—385年10月16日），字永固，一名文玉，略阳临渭（今甘肃秦安）人，氐族，苻雄之子，苻洪之孙，苻健之侄，是十六国时期前秦的君主，称大秦天王。", "img": {"src": "portraits/fujian.webp", "w": 240, "h": 380, "file": "File:Harvard drs 49802792 繡像三國演義續編 v.1 (苻堅).jpg", "page": "https://commons.wikimedia.org/wiki/File:Harvard_drs_49802792_%E7%B9%A1%E5%83%8F%E4%B8%89%E5%9C%8B%E6%BC%94%E7%BE%A9%E7%BA%8C%E7%B7%A8_v.1_(%E8%8B%BB%E5%A0%85).jpg", "license": "Public domain", "artist": "see below"}}, "chenqingzhi": {"title": "陈庆之", "revid": 91731593, "date": "2026-03-02", "brief": "陈庆之（484年—539年），字子云，义兴郡国山县（今江苏省宜兴市）人，中国南北朝南朝梁武将。"}, "gaohuan": {"title": "高欢", "revid": 94378748, "date": "2026-09-15", "brief": "高欢（496年—547年2月13日），鲜卑名贺六浑，勃海郡蓨县（今河北省衡水市景县）人，鲜卑化汉人，北魏、东魏权臣，任职相国，爵封“渤海王”，谥“献武”，也是北齐政权的奠基者。", "img": {"src": "portraits/gaohuan.webp", "w": 240, "h": 325, "file": "File:渤海王高歡（北史演義）.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E6%B8%A4%E6%B5%B7%E7%8E%8B%E9%AB%98%E6%AD%A1%EF%BC%88%E5%8C%97%E5%8F%B2%E6%BC%94%E7%BE%A9%EF%BC%89.jpg", "license": "Public domain", "artist": "Unknown author"}}, "yuwentai": {"title": "宇文泰", "revid": 93997833, "date": "2026-08-22", "brief": "宇文泰（505年—556年11月21日），字黑獭（一作黑泰），代郡武川镇（今内蒙古自治区呼和浩特市武川县）人，鲜卑宇文部后裔，北朝西魏权臣，爵封“安定公”，谥“文”，亦是北周政…", "img": {"src": "portraits/yuwentai.webp", "w": 240, "h": 327, "file": "File:宇文丞相黑獺（北史演義）.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E5%AE%87%E6%96%87%E4%B8%9E%E7%9B%B8%E9%BB%91%E7%8D%BA%EF%BC%88%E5%8C%97%E5%8F%B2%E6%BC%94%E7%BE%A9%EF%BC%89.jpg", "license": "Public domain", "artist": "Unknown author"}}, "gaochanggong": {"title": "高長恭", "revid": 94466344, "date": "2026-09-20", "brief": "高长恭（541年？—573年7月28日），名肃，一名孝瓘，字长恭，以字行，勃海郡蓨县（今河北省衡水市景县）人，追尊齐神武帝高欢之孙，追尊齐文襄帝高澄第三子，生母不详，北齐宗室…", "img": {"src": "portraits/gaochanggong.webp", "w": 240, "h": 159, "file": "File:Ryouou (Lanling) statue at Miyajimaguchi.jpg", "page": "https://commons.wikimedia.org/wiki/File:Ryouou_(Lanling)_statue_at_Miyajimaguchi.jpg", "license": "CC BY-SA 4.0", "artist": "Gisling"}}, "duguxin": {"title": "独孤信", "revid": 94648629, "date": "2026-09-29", "brief": "独孤信（503年—557年），本名如愿，鲜卑名期弥头，云中（今山西大同市）人，为匈奴裔鲜卑人，其先出自匈奴，西魏八柱国之一。官至太保、大宗伯、卫国公。"}, "gukaizhi": {"title": "顾恺之", "revid": 89469433, "date": "2025-10-10", "brief": "顾恺之（约348年—409年），字长康，东晋人，是一位出身晋陵无锡（今江苏无锡）的画家与官员，以其人物画作品著称。", "img": {"src": "portraits/gukaizhi.webp", "w": 240, "h": 329, "file": "File:Gu Kaizhi.jpg", "page": "https://commons.wikimedia.org/wiki/File:Gu_Kaizhi.jpg", "license": "Public domain", "artist": "佚名"}}, "zuchongzhi": {"title": "祖冲之", "revid": 94127669, "date": "2026-08-31", "brief": "祖冲之（429年—500年），字文远，范阳郡逎县（今河北省保定市涞水县）人，刘宋时代杰出的数学家、天文学家，主要成就在数学、天文历法和机械制造三个领域。", "img": {"src": "portraits/zuchongzhi.webp", "w": 240, "h": 361, "file": "File:祖冲之铜像.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E7%A5%96%E5%86%B2%E4%B9%8B%E9%93%9C%E5%83%8F.jpg", "license": "CC BY-SA 4.0", "artist": "三猎"}}, "taohongjing": {"title": "陶弘景", "revid": 92726316, "date": "2026-05-20", "brief": "陶弘景（456年4月30日—536年3月12日；南朝宋孝武帝孝建三年－梁武帝大同二年），字通明，自号华阳隐居，赐号贞白先生，丹阳秣陵（今中华人民共和国江苏省南京市江宁区）人，南…", "img": {"src": "portraits/taohongjing.webp", "w": 150, "h": 232, "file": "File:TaoHongJing.jpg", "page": "https://commons.wikimedia.org/wiki/File:TaoHongJing.jpg", "license": "Public domain", "artist": "佚名"}}, "lidaoyuan": {"title": "郦道元", "revid": 94012548, "date": "2026-08-23", "brief": "郦道元（466年或472年—527年），字善长，范阳郡涿县（今河北省涿州市）人，北魏地理学家、散文家。曾任东荆州刺史，因得罪权贵，被免去官职。十年后，朝廷复起用为着河南尹。"}, "jiasixie": {"title": "贾思勰", "revid": 89380844, "date": "2025-10-03", "brief": "贾思勰（xié）（？—？），齐郡益都县（今山东省寿光市西南），北魏农学家，官至高阳郡太守（今山东省淄博市临淄区一带）。", "img": {"src": "portraits/jiasixie.webp", "w": 240, "h": 180, "file": "File:贾思勰像.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E8%B4%BE%E6%80%9D%E5%8B%B0%E5%83%8F.jpg", "license": "CC BY-SA 4.0", "artist": "Ngguls"}}, "liuxie": {"title": "刘勰", "revid": 91127469, "date": "2026-01-16", "brief": "刘勰（xié）（约460年至480年—约522年至538年），字彦和，法名慧地，祖籍东莞郡莒县（今山东省日照市莒县），居京口（今江苏镇江），是南朝时期的文学理论批评家。"}, "xiedaoyun": {"title": "謝道韞", "revid": 93897532, "date": "2026-08-15", "brief": "谢道韫（346年—409年），字令姜，陈郡阳夏县（今河南省周口市太康县）人，东晋时期著名诗人，原有诗集数卷，今多数以遗失，仅有《登山》、《拟稽中散咏松》等零星作品存世。", "img": {"src": "portraits/xiedaoyun.webp", "w": 240, "h": 345, "file": "File:Xie Daoyun.jpg", "page": "https://commons.wikimedia.org/wiki/File:Xie_Daoyun.jpg", "license": "Public domain", "artist": "Although it proclaimed the copyright, but the image is scanned from a Chinese book which was published at 1772, named as"}}, "duguhuanghou": {"title": "獨孤伽羅", "revid": 94783023, "date": "2026-10-06", "brief": "独孤伽罗（544年—602年9月15日），河南郡洛阳县（今河南省洛阳市东）人，北周太保、大宗伯独孤信的七女，母崔氏，隋朝开国皇帝隋文帝的妻子，北周宣帝皇后杨丽华、杨勇、隋炀帝杨…"}, "yangsu": {"title": "楊素", "revid": 93983373, "date": "2026-08-21", "brief": "杨素（544年—606年8月31日），字处道，弘农郡华阴县（今陕西省华阴市）人，出自弘农杨氏越公房，北周、隋朝军事家、诗人。", "img": {"src": "portraits/yangsu.webp", "w": 240, "h": 315, "file": "File:Yang Su.jpg", "page": "https://commons.wikimedia.org/wiki/File:Yang_Su.jpg", "license": "Public domain", "artist": "a Ming Dynasty Artist"}}, "changsunwuji": {"title": "长孙无忌", "revid": 94507833, "date": "2026-09-23", "brief": "长孙无忌（594年？—659年），字辅机，河南郡洛阳县（今河南省洛阳市东）人。唐初大臣和外戚，，封齐国公、赵国公，凌烟阁二十四功臣之首。唐太宗长孙皇后之兄，唐高宗的舅父。", "img": {"src": "portraits/changsunwuji.webp", "w": 240, "h": 360, "file": "File:Chinese - The Twenty-Four Ministers of the Tang -T'ang- Dynasty Emperor Taizong -T'ai-Tsung- - Walters 3557 - Changsun Wuji.png", "page": "https://commons.wikimedia.org/wiki/File:Chinese_-_The_Twenty-Four_Ministers_of_the_Tang_-T%27ang-_Dynasty_Emperor_Taizong_-T%27ai-Tsung-_-_Walters_3557_-_Changsun_Wuji.png", "license": "Public domain", "artist": "Unknown author"}}, "duruhui": {"title": "杜如晦", "revid": 93053780, "date": "2026-06-13", "brief": "杜如晦（585年—630年5月6日），字克明，京兆郡杜陵县（今陕西省西安市长安区）人，唐朝初期大臣。他是李世民夺取政权、开创贞观之治中的主要谋臣之一，深受李世民的重用。", "img": {"src": "portraits/duruhui.webp", "w": 240, "h": 343, "file": "File:杜如晦.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E6%9D%9C%E5%A6%82%E6%99%A6.jpg", "license": "Public domain", "artist": "Unknown author"}}, "xuerenhui": {"title": "薛仁貴", "revid": 93525613, "date": "2026-07-17", "brief": "薛仁贵（614年—683年），名礼，字仁贵，以字行，绛州龙门县（今山西省河津市）人，祖籍河东郡汾阴县（今山西省运城市万荣县）。", "img": {"src": "portraits/xuerenhui.webp", "w": 240, "h": 343, "file": "File:天山三箭.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E5%A4%A9%E5%B1%B1%E4%B8%89%E7%AE%AD.jpg", "license": "Public domain", "artist": "Ma Tai (馬駘; 1885-1937)"}}, "shangguanwaner": {"title": "上官婉儿", "revid": 93881379, "date": "2026-08-13", "brief": "上官婉儿（664年11月24日至12月22日—710年7月21日），唐朝陕州陕县人（今河南三门峡），祖籍陇西上邽（今甘肃天水），是女官、政治家、诗人，为唐高宗宰相上官仪的孙女…", "img": {"src": "portraits/shangguanwaner.webp", "w": 240, "h": 399, "file": "File:美人百態畫譜之上官昭容（Consort Shangguan）.png", "page": "https://commons.wikimedia.org/wiki/File:%E7%BE%8E%E4%BA%BA%E7%99%BE%E6%85%8B%E7%95%AB%E8%AD%9C%E4%B9%8B%E4%B8%8A%E5%AE%98%E6%98%AD%E5%AE%B9%EF%BC%88Consort_Shangguan%EF%BC%89.png", "license": "Public domain", "artist": "Ma Dai（馬駘、1886～1937）"}}, "yaochong": {"title": "姚崇", "revid": 92178076, "date": "2026-04-06", "brief": "姚崇（651年—721年9月28日），原名元崇，后名元之，其后为了避唐玄宗的“开元”年号之讳，改名为姚崇，陕州硖石县人，唐朝宰相。", "img": {"src": "portraits/yaochong.webp", "w": 240, "h": 352, "file": "File:Portraits of Famous Men - Yao Chong.jpg", "page": "https://commons.wikimedia.org/wiki/File:Portraits_of_Famous_Men_-_Yao_Chong.jpg", "license": "Public domain", "artist": "Unknown Chinese artist"}}, "zhangjiuling": {"title": "张九龄", "revid": 94748036, "date": "2026-10-04", "brief": "张九龄（678年—740年6月5日），字子寿，一名博物，韶州曲江人（今广东省韶关市曲江区），客家人。唐代第一位由岭南书生进身的宰相、诗人。卒谥文献。人称“张曲江”。", "img": {"src": "portraits/zhangjiuling.webp", "w": 240, "h": 181, "file": "File:Zhangjiuling.jpg", "page": "https://commons.wikimedia.org/wiki/File:Zhangjiuling.jpg", "license": "CC BY-SA 3.0", "artist": "The original uploader was Zhuwq at Chinese Wikipedia."}}, "yanzhenqing": {"title": "颜真卿", "revid": 93046269, "date": "2026-06-13", "brief": "颜真卿（709年—785年8月23日），字清臣，小名羡门子，别号应方，京兆府长安县（今陕西省西安市）人，祖籍琅邪郡临沂县（今山东省临沂市），唐朝政治家、书法家。", "img": {"src": "portraits/yanzhenqing.webp", "w": 240, "h": 336, "file": "File:唐名臣像-13-顔魯公.png", "page": "https://commons.wikimedia.org/wiki/File:%E5%94%90%E5%90%8D%E8%87%A3%E5%83%8F-13-%E9%A1%94%E9%AD%AF%E5%85%AC.png", "license": "Public domain", "artist": "Unknown author"}}, "yangguifei": {"title": "杨贵妃", "revid": 94409764, "date": "2026-09-17", "brief": "杨贵妃（719年6月22日—756年7月15日），号太真，蒲州永乐（今山西永济）人，是唐玄宗宠妃，中国四大美人之一。", "img": {"src": "portraits/yangguifei.webp", "w": 240, "h": 278, "file": "File:上马图.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E4%B8%8A%E9%A9%AC%E5%9B%BE.jpg", "license": "Public domain", "artist": "Qian Xuan"}}, "anlushan": {"title": "安祿山", "revid": 93957888, "date": "2026-08-20", "brief": "安禄山（703年2月19日—757年1月25日），本姓康，名轧荦山，营州柳城（今辽宁省朝阳市）人。母阿史德氏。父为昭武九姓的粟特人，母为突厥巫师，信仰祆教。", "img": {"src": "portraits/anlushan.webp", "w": 240, "h": 319, "file": "File:帝鉴图说.Recueil Historique des Principaux Traits de la Vie des Empereurs Chinois.95帧图.彩绘册页.约18世纪 (page 19 宠幸番将) (安禄山) (cropped).jpg", "page": "https://commons.wikimedia.org/wiki/File:%E5%B8%9D%E9%89%B4%E5%9B%BE%E8%AF%B4.Recueil_Historique_des_Principaux_Traits_de_la_Vie_des_Empereurs_Chinois.95%E5%B8%A7%E5%9B%BE.%E5%BD%A9%E7%BB%98%E5%86%8C%E9%A1%B5.%E7%BA%A618%E4%B8%96%E7%BA%AA_(page_19_%E5%AE%A0%E5%B9%B8%E7%95%AA%E5%B0%86)_(%E5%AE%89%E7%A6%84%E5%B1%B1)_(cropped).jpg", "license": "CC0", "artist": "书格"}}, "libi": {"title": "李泌", "revid": 94401800, "date": "2026-09-17", "brief": "李泌（722年5月15日—789年4月1日），字长源，京兆人，祖籍辽东襄平，唐朝宰相。", "img": {"src": "portraits/libi.webp", "w": 240, "h": 320, "file": "File:Li Bi, WuShuangPu (1694, 1996).jpg", "page": "https://commons.wikimedia.org/wiki/File:Li_Bi,_WuShuangPu_(1694,_1996).jpg", "license": "Public domain", "artist": "Jin Guliang (original 1694)"}}, "liuyuxi": {"title": "刘禹锡", "revid": 94339549, "date": "2026-09-13", "brief": "刘禹锡（772年—842年），字梦得，河南郡洛阳县人。唐朝著名诗人、哲学家，中唐文学的代表人物之一，有诗豪之称。", "img": {"src": "portraits/liuyuxi.webp", "w": 240, "h": 339, "file": "File:刘禹锡像.JPG", "page": "https://commons.wikimedia.org/wiki/File:%E5%88%98%E7%A6%B9%E9%94%A1%E5%83%8F.JPG", "license": "CC BY-SA 3.0", "artist": "Gisling"}}, "dumu": {"title": "杜牧", "revid": 91732836, "date": "2026-03-02", "brief": "杜牧（803年—852年），字牧之，号樊川居士，京兆府万年县人，晚唐士大夫与作家。", "img": {"src": "portraits/dumu.webp", "w": 240, "h": 439, "file": "File:Du Mu.jpg", "page": "https://commons.wikimedia.org/wiki/File:Du_Mu.jpg", "license": "Public domain", "artist": "佚名"}}, "liugongquan": {"title": "柳公權", "revid": 92533324, "date": "2026-05-04", "brief": "柳公权（778年—865年），字诚悬，京兆府华原县（今陕西省铜川市耀州区）人，祖籍河东郡解县（今山西省运城市临猗县），出自河东柳氏东眷，唐朝大书法家。", "img": {"src": "portraits/liugongquan.webp", "w": 240, "h": 339, "file": "File:柳公权.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E6%9F%B3%E5%85%AC%E6%9D%83.jpg", "license": "Public domain", "artist": "Unknown author"}}, "huangchao": {"title": "黄巢", "revid": 94521184, "date": "2026-09-23", "brief": "黄巢（835年—884年），曹州冤句（今山东菏泽西南）人，大齐开国君主。初为盐帮首领，售私盐为业，后成为反抗大唐的民变军首领，并自立为帝，尊号为承天应运启圣睿文宣武皇帝，国号大…", "img": {"src": "portraits/huangchao.webp", "w": 240, "h": 391, "file": "File:黃巢（殘唐五代史演義傳）.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E9%BB%83%E5%B7%A2%EF%BC%88%E6%AE%98%E5%94%90%E4%BA%94%E4%BB%A3%E5%8F%B2%E6%BC%94%E7%BE%A9%E5%82%B3%EF%BC%89.jpg", "license": "Public domain", "artist": "Unknown author"}}, "likeiyong": {"title": "李克用", "revid": 93843994, "date": "2026-08-11", "brief": "李克用（856年10月24日—908年2月24日），字翼圣，神武川之新城（今山西代县）人，后唐庄宗李存勗之父，本姓朱邪（又作朱耶），其父受唐朝天子赐李姓。", "img": {"src": "portraits/likeiyong.webp", "w": 240, "h": 503, "file": "File:Li Keyong.jpg", "page": "https://commons.wikimedia.org/wiki/File:Li_Keyong.jpg", "license": "Public domain", "artist": "Unknown artist"}}, "shijingtang": {"title": "石敬瑭", "revid": 94203020, "date": "2026-09-05", "brief": "晋高祖石敬瑭（892年3月30日—942年7月28日），五代十国时期的后晋开国皇帝（在位：936年11月28日－942年7月28日）。庙号高祖，谥号圣文章武明德孝皇帝。", "img": {"src": "portraits/shijingtang.webp", "w": 240, "h": 267, "file": "File:Shi Jingtang (Jin Gaozu).jpg", "page": "https://commons.wikimedia.org/wiki/File:Shi_Jingtang_(Jin_Gaozu).jpg", "license": "Public domain", "artist": "Unknown author"}}, "liuzhiyuan": {"title": "劉知遠", "revid": 92923132, "date": "2026-06-02", "brief": "后汉高祖刘知远（895年3月4日—948年3月10日），并州晋阳（今山西太原）人，五代时期后汉开国皇帝，沙陀族，即位后改名为刘暠，947年－948年在位，谥号为睿文圣武昭肃孝皇…", "img": {"src": "portraits/liuzhiyuan.webp", "w": 240, "h": 278, "file": "File:Liu Zhiyuan (Han Gaozu).jpg", "page": "https://commons.wikimedia.org/wiki/File:Liu_Zhiyuan_(Han_Gaozu).jpg", "license": "Public domain", "artist": "Unknown author"}}, "guowei": {"title": "郭威", "revid": 91476687, "date": "2026-02-10", "brief": "周太祖郭威（904年9月10日—954年2月21日），字文仲，小名“郭雀儿”，籍贯邢州尧山（今河北隆尧）。五代时期后周开国皇帝（951年—954年）。", "img": {"src": "portraits/guowei.webp", "w": 240, "h": 269, "file": "File:Guo Wei (Zhou Taizu).jpg", "page": "https://commons.wikimedia.org/wiki/File:Guo_Wei_(Zhou_Taizu).jpg", "license": "Public domain", "artist": "Unknown author"}}, "lisiyuan": {"title": "李嗣源", "revid": 93808984, "date": "2026-08-08", "brief": "唐明宗李亶（867年10月10日—933年12月15日），初名嗣源，小名邈佶烈，应州金城县（今山西省应县）人，沙陀族，五代十国时期后唐第二位皇帝（926年6月3日－933年12…", "img": {"src": "portraits/lisiyuan.webp", "w": 240, "h": 346, "file": "File:唐明宗.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E5%94%90%E6%98%8E%E5%AE%97.jpg", "license": "Public domain", "artist": "清善成堂刻本"}}, "zhaopu": {"title": "赵普", "revid": 91811556, "date": "2026-03-08", "brief": "赵普（922年—992年8月14日），字则平。北宋初年宰相。在陈桥兵变中立功，协助赵匡胤登上帝位，为宋开国功臣。", "img": {"src": "portraits/zhaopu.webp", "w": 240, "h": 326, "file": "File:宋丞相赵普.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E5%AE%8B%E4%B8%9E%E7%9B%B8%E8%B5%B5%E6%99%AE.jpg", "license": "Public domain", "artist": "Unknown author"}}, "kouzhun": {"title": "寇準", "revid": 94779385, "date": "2026-10-05", "brief": "寇准（961年—1023年10月24日），字平仲，华州下邽（今陕西渭南）人，北宋大臣。与白居易、张仁愿并称“渭南三贤”。", "img": {"src": "portraits/kouzhun.webp", "w": 240, "h": 328, "file": "File:宋丞相寇莱公准.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E5%AE%8B%E4%B8%9E%E7%9B%B8%E5%AF%87%E8%8E%B1%E5%85%AC%E5%87%86.jpg", "license": "Public domain", "artist": "Unknown author"}}, "diqing": {"title": "狄青", "revid": 93806541, "date": "2026-08-07", "brief": "狄青（1008年—1057年5月3日），字汉臣，北宋河东路汾州西河（即今山西汾阳）人，出身寒门。", "img": {"src": "portraits/diqing.webp", "w": 240, "h": 439, "file": "File:Ti Ching.jpg", "page": "https://commons.wikimedia.org/wiki/File:Ti_Ching.jpg", "license": "Public domain", "artist": "佚名"}}, "yangye": {"title": "杨业", "revid": 92922983, "date": "2026-06-02", "brief": "杨业（923年—986年），又名继业，最初名为重贵，河东路并州太原（今山西省太原市）阳曲人，北宋抗辽将领。", "img": {"src": "portraits/yangye.webp", "w": 220, "h": 290, "file": "File:Yangye 1892.jpg", "page": "https://commons.wikimedia.org/wiki/File:Yangye_1892.jpg", "license": "Public domain", "artist": "Illustrator unknown, novelist = Xiong Damu (熊大木) (Life time: This is from a book printed 120 years ago.)"}}, "yanshu": {"title": "晏殊", "revid": 93129012, "date": "2026-06-19", "brief": "晏殊（991年—1055年2月27日），字同叔，江西抚州临川县文港乡（今南昌市进贤县文港镇）人，北宋前期政治家、婉约派词人，与欧阳修并称“晏欧”。他本人又被称为“太平宰相”。"}, "liuyong": {"title": "柳永", "revid": 91791417, "date": "2026-03-07", "brief": "柳永（985年—1053年），原名三变，字景庄，后改名永，改字耆卿，福建路建宁军崇安县人，生于京东路济州任城县，排行第七，时人或称柳七而不直称其名，以屯田员外郎致仕，故又称柳屯…", "img": {"src": "portraits/liuyong.webp", "w": 240, "h": 135, "file": "File:柳永和歌妓大理石像.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E6%9F%B3%E6%B0%B8%E5%92%8C%E6%AD%8C%E5%A6%93%E5%A4%A7%E7%90%86%E7%9F%B3%E5%83%8F.jpg", "license": "CC BY-SA 4.0", "artist": "WQL"}}, "zhoudunyi": {"title": "周敦颐", "revid": 93896133, "date": "2026-08-15", "brief": "周敦颐（1017年—1073年7月24日），原名敦实，字茂叔，后避宋英宗讳，改名敦颐，号濂溪，学者称濂溪先生。", "img": {"src": "portraits/zhoudunyi.webp", "w": 240, "h": 326, "file": "File:宋提刑周敦颐.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E5%AE%8B%E6%8F%90%E5%88%91%E5%91%A8%E6%95%A6%E9%A2%90.jpg", "license": "Public domain", "artist": "Unknown author"}}, "chenghao": {"title": "程顥", "revid": 92296047, "date": "2026-04-16", "brief": "程颢hào（1032年—1085年），字伯淳，号明道，世称明道先生。北宋学者、政治家，北宋嘉祐二年（1057年）进士，历官鄠县主簿、上元县主簿、泽州晋城令、太子中允、监察御史…", "img": {"src": "portraits/chenghao.webp", "w": 240, "h": 332, "file": "File:宋监察御史程颢.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E5%AE%8B%E7%9B%91%E5%AF%9F%E5%BE%A1%E5%8F%B2%E7%A8%8B%E9%A2%A2.jpg", "license": "Public domain", "artist": "Unknown author"}}, "chengyi": {"title": "程颐", "revid": 87105856, "date": "2025-05-03", "brief": "程颐（1033年—1107年），字正叔，世居中山，北宋河南伊川（今河南省洛阳市伊川县）人，世称伊川先生，北宋理学家、教育家，历官汝州团练推官、西京国子监教授。", "img": {"src": "portraits/chengyi.webp", "w": 240, "h": 329, "file": "File:宋崇政殿说书程颐.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E5%AE%8B%E5%B4%87%E6%94%BF%E6%AE%BF%E8%AF%B4%E4%B9%A6%E7%A8%8B%E9%A2%90.jpg", "license": "Public domain", "artist": "Unknown author"}}, "mifu": {"title": "米芾", "revid": 94766448, "date": "2026-10-05", "brief": "米芾（fú）（1051年—1107年），初名黻（fú），字元章，号襄阳漫士、海岳外史、鹿门居士，太原人，北宋书法家、书画理论家、画家、鉴定家、收藏家。", "img": {"src": "portraits/mifu.webp", "w": 240, "h": 255, "file": "File:米芾.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E7%B1%B3%E8%8A%BE.jpg", "license": "Public domain", "artist": "Chao Bu's Painting"}}, "huangtingjian": {"title": "黃庭堅", "revid": 94655707, "date": "2026-09-30", "brief": "黄庭坚（1045年—1105年），字鲁直，号山谷道人、豫章先生，晚号涪翁，洪州分宁（今江西九江市修水县）人，亦自称为南昌人。北宋诗人、书法家，江西诗派祖师。", "img": {"src": "portraits/huangtingjian.webp", "w": 240, "h": 335, "file": "File:黄庭坚.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E9%BB%84%E5%BA%AD%E5%9D%9A.jpg", "license": "Public domain", "artist": "Unknown author"}}, "zongze": {"title": "宗澤", "revid": 94758470, "date": "2026-10-04", "brief": "宗泽（1060年1月20日—1128年7月29日），字汝霖，婺州义乌人，中国宋朝名臣，南宋高宗时任东京留守兼知开封府，重用岳飞北伐，并多次请高宗迁回开封府未果，为权臣所抑，积愤…", "img": {"src": "portraits/zongze.webp", "w": 240, "h": 367, "file": "File:宗澤.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E5%AE%97%E6%BE%A4.jpg", "license": "Public domain", "artist": "清顾沅辑"}}, "hanshizhong": {"title": "韩世忠", "revid": 90858100, "date": "2025-12-27", "brief": "韩世忠（1089年—1151年9月16日），字良臣，绥德军（今陕西省绥德县）人，南宋名将。", "img": {"src": "portraits/hanshizhong.webp", "w": 240, "h": 533, "file": "File:韓世忠.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E9%9F%93%E4%B8%96%E5%BF%A0.jpg", "license": "Public domain", "artist": "劉松年繪"}}, "ligang": {"title": "李纲", "revid": 93789689, "date": "2026-08-06", "brief": "李纲（1083年7月27日—1140年2月5日），字伯纪，祖籍福建邵武，父祖迁居无锡东乡胶山，故自号梁溪居士（梁溪为无锡古称）。", "img": {"src": "portraits/ligang.webp", "w": 240, "h": 413, "file": "File:Li Kang.jpg", "page": "https://commons.wikimedia.org/wiki/File:Li_Kang.jpg", "license": "Public domain", "artist": "佚名"}}, "qinhui": {"title": "秦桧", "revid": 94213260, "date": "2026-09-06", "brief": "秦桧（huì）（1091年1月17日—1155年11月18日），字会之，江宁府（今江苏南京江宁）人，南宋初年的宠臣、书法家、诗人，官至太师，其生前的爵位封至建康郡王。", "img": {"src": "portraits/qinhui.webp", "w": 240, "h": 393, "file": "File:秦檜.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E7%A7%A6%E6%AA%9C.jpg", "license": "Public domain", "artist": "AnonymousUnknown author"}}, "yeludashi": {"title": "耶律大石", "revid": 93104421, "date": "2026-06-17", "brief": "辽德宗耶律大石（1087年或1094年—1143年），又称大石林牙或林牙大石。字重德，契丹人。西辽开国皇帝，庙号德宗，在位12年。", "img": {"src": "portraits/yeludashi.webp", "w": 240, "h": 140, "file": "File:KaraKhitaiAD1200.png", "page": "https://commons.wikimedia.org/wiki/File:KaraKhitaiAD1200.png", "license": "CC BY 3.0", "artist": "Gabagool"}}, "wanyanzongbi": {"title": "兀朮", "revid": 94525363, "date": "2026-09-23", "brief": "完颜宗弼（1090年代—1148年11月19日），女真名斡啜，一作兀朮（zhú），又名乌珠，汉姓王，名宗弼（民间常称为金兀朮（zhú））。", "img": {"src": "portraits/wanyanzongbi.webp", "w": 240, "h": 320, "file": "File:兀术像.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E5%85%80%E6%9C%AF%E5%83%8F.jpg", "license": "CC BY-SA 4.0", "artist": "千里走单骑"}}, "yuanhaowen": {"title": "元好问", "revid": 94546528, "date": "2026-09-25", "brief": "元好问（1190年8月10日—1257年10月12日），字裕之，号遗山，山西太原府秀容县（今山西忻州市）人，世称遗山先生。金、元之际文学家。", "img": {"src": "portraits/yuanhaowen.webp", "w": 240, "h": 180, "file": "File:山西省忻州市忻府區韓岩村元好問墓的元好問銅像.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E5%B1%B1%E8%A5%BF%E7%9C%81%E5%BF%BB%E5%B7%9E%E5%B8%82%E5%BF%BB%E5%BA%9C%E5%8D%80%E9%9F%93%E5%B2%A9%E6%9D%91%E5%85%83%E5%A5%BD%E5%95%8F%E5%A2%93%E7%9A%84%E5%85%83%E5%A5%BD%E5%95%8F%E9%8A%85%E5%83%8F.jpg", "license": "CC BY-SA 4.0", "artist": "Outlookxp"}}, "yeluhongji": {"title": "辽道宗", "revid": 93669479, "date": "2026-07-27", "brief": "辽道宗耶律洪基（辽史等作洪基；1032年9月14日—1101年2月12日），契丹及辽朝第八位皇帝（1055年8月28日—1101年2月12日在位），在位长达46年，仅次于辽圣宗…"}, "wanyanjing": {"title": "金章宗", "revid": 90983707, "date": "2026-01-04", "brief": "金章宗完颜璟（1168年8月31日（农历七月二十七）—1208年12月29日），女真名麻达葛，金朝第6位皇帝（1189年1月20日—1208年12月29日在位），在位20年，享…"}, "tolui": {"title": "拖雷", "revid": 94696337, "date": "2026-10-01", "brief": "拖雷（蒙古语：ᠲᠤᠯᠤᠢ，汉语拼音字母：Tôlûi，鲍培转写：Tolui，西里尔字母：Толуй；意为“镜子”；", "img": {"src": "portraits/tolui.webp", "w": 240, "h": 185, "file": "File:TuluiWithQueenSorgaqtani.jpg", "page": "https://commons.wikimedia.org/wiki/File:TuluiWithQueenSorgaqtani.jpg", "license": "Public domain", "artist": "Rashid al-Din"}}, "ogedei": {"title": "窝阔台", "revid": 94817185, "date": "2026-10-07", "brief": "窝阔台汗（蒙古语：ᠦᠭᠡᠳᠡᠢᠬᠠᠭᠠᠨ，鲍培转写：Ögedeiqaγan，秘史记音：斡歌歹·中合罕，西里尔字母：Өгөдэйхаан；", "img": {"src": "portraits/ogedei.webp", "w": 240, "h": 305, "file": "File:YuanEmperorAlbumOgedeiPortrait.jpg", "page": "https://commons.wikimedia.org/wiki/File:YuanEmperorAlbumOgedeiPortrait.jpg", "license": "Public domain", "artist": "AnonymousUnknown author"}}, "hulagu": {"title": "旭烈兀", "revid": 93992039, "date": "2026-08-22", "brief": "旭烈兀（蒙古语：ᠬᠦᠯᠡᠭᠦᠬᠠᠨ，鲍培转写：Hülegüqan，西里尔字母：Хүлэгүхан，名字意为“战士”，1217年—1265年2月8日），蒙古人，蒙古第三次西征主帅…", "img": {"src": "portraits/hulagu.webp", "w": 240, "h": 154, "file": "File:HulaguAndDokuzKathun.JPG", "page": "https://commons.wikimedia.org/wiki/File:HulaguAndDokuzKathun.JPG", "license": "Public domain", "artist": "Rachid Ad-Din"}}, "bayan": {"title": "伯顏 (八鄰部)", "revid": 91291414, "date": "2026-01-28", "brief": "伯颜（蒙古语：ᠪᠠᠶᠠᠨ，鲍培转写：Bayan，西里尔字母：Баян；1236年—1295年1月11日），出身八邻部，元朝初年的军事家和政治人物。"}, "zhanghongfan": {"title": "張弘範", "revid": 93356144, "date": "2026-07-07", "brief": "张弘范（1238年—1280年2月11日），字仲畴，元朝将领，易州定兴（辽朝时期属于南京道管辖，金朝时期属于中都路管辖，今属河北）人。"}, "guahanqing": {"title": "关汉卿", "revid": 90839454, "date": "2025-12-25", "brief": "关汉卿（？—？），号已斋（一作一斋）、已斋叟，大都（今北京市）人，为“元曲四大家”之首。", "img": {"src": "portraits/guahanqing.webp", "w": 240, "h": 309, "file": "File:Ji50, 3-2, Portrait of Guan Hanqing, 1958.jpg", "page": "https://commons.wikimedia.org/wiki/File:Ji50,_3-2,_Portrait_of_Guan_Hanqing,_1958.jpg", "license": "Public domain", "artist": "佚名"}}, "mazhiyuan": {"title": "马致远", "revid": 93277104, "date": "2026-07-01", "brief": "马致远（1255年—1321年），字千里，号东篱，大都人，元代初期杂剧作家，人称“曲状元”、“马神仙”。与关汉卿、白朴和郑光祖并称元曲四大家。", "img": {"src": "portraits/mazhiyuan.webp", "w": 240, "h": 320, "file": "File:Statue of Ma Zhiyuan, Former Residence of Ma Zhiyuan.jpg", "page": "https://commons.wikimedia.org/wiki/File:Statue_of_Ma_Zhiyuan,_Former_Residence_of_Ma_Zhiyuan.jpg", "license": "CC BY 3.0", "artist": "翟万增"}}, "wangmian": {"title": "王冕", "revid": 87397039, "date": "2025-05-22", "brief": "王冕（1287或1310年—1359年），字元章，号煮石山农、饭牛翁、会稽外史、梅花屋主等，诸暨（今属浙江绍兴）人。元朝画家、学者、诗人和篆刻家。", "img": {"src": "portraits/wangmian.webp", "w": 240, "h": 80, "file": "File:Wang Mian-Ink Plum2.jpg", "page": "https://commons.wikimedia.org/wiki/File:Wang_Mian-Ink_Plum2.jpg", "license": "Public domain", "artist": "Wang Mian"}}, "xuda": {"title": "徐達", "revid": 94775200, "date": "2026-10-05", "brief": "徐达（1332年—1385年），字天德，濠州钟离永丰乡（今安徽凤阳东北）人，明朝开国功臣。元朝末年，徐达参加了朱元璋军队，追随其击败陈友谅、张士诚，朱元璋任为左相国。", "img": {"src": "portraits/xuda.webp", "w": 240, "h": 430, "file": "File:Xu Da.jpg", "page": "https://commons.wikimedia.org/wiki/File:Xu_Da.jpg", "license": "Public domain", "artist": "佚名"}}, "changyuchun": {"title": "常遇春", "revid": 94775136, "date": "2026-10-05", "brief": "常遇春（1330年—1369年8月9日），字伯仁，号燕衡。南直隶凤阳怀远（今属安徽）人，明朝开国名将。", "img": {"src": "portraits/changyuchun.webp", "w": 240, "h": 396, "file": "File:開平王常遇春坐像.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E9%96%8B%E5%B9%B3%E7%8E%8B%E5%B8%B8%E9%81%87%E6%98%A5%E5%9D%90%E5%83%8F.jpg", "license": "Public domain", "artist": "Unknown author"}}, "xiejin": {"title": "解縉", "revid": 91623197, "date": "2026-02-22", "brief": "解缙（1369年—1415年2月22日），字大绅，号春雨，谥文毅，江西吉水州（今江西吉安吉水县鉴湖）人，明朝第一位内阁首辅，主编《明太祖实录》与《永乐大典》。", "img": {"src": "portraits/xiejin.webp", "w": 240, "h": 279, "file": "File:解縉.png", "page": "https://commons.wikimedia.org/wiki/File:%E8%A7%A3%E7%B8%89.png", "license": "Public domain", "artist": "顾建龙（1606-？）"}}, "yangtinghe": {"title": "楊廷和", "revid": 89939852, "date": "2025-11-12", "brief": "杨廷和（1459年10月15日—1529年7月25日），字介夫，号石斋，四川成都府新都县（今成都市新都区马家镇升庵村）人，祖籍江西庐陵。明朝中期重臣、内阁首辅。", "img": {"src": "portraits/yangtinghe.webp", "w": 240, "h": 337, "file": "File:Yang Tinghe.png", "page": "https://commons.wikimedia.org/wiki/File:Yang_Tinghe.png", "license": "Public domain", "artist": "Unknown author"}}, "xujie": {"title": "徐階", "revid": 94395032, "date": "2026-09-16", "brief": "徐阶（1503年10月9日—1583年），字子升，号少湖，一号存斋，直隶松江府华亭县（今上海市松江区）人，明代政治家、文学家及思想家，官至内阁首辅、吏部尚书、建极殿大学士。", "img": {"src": "portraits/xujie.webp", "w": 240, "h": 223, "file": "File:徐階.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E5%BE%90%E9%9A%8E.jpg", "license": "Public domain", "artist": "​清 徐璋"}}, "gaogong": {"title": "高拱", "revid": 92977304, "date": "2026-06-07", "brief": "高拱（1513年1月19日—1578年8月4日），字肃卿，号中玄，河南开封府钧州新郑县人，祖籍腹里洪洞，明朝政治人物，官至吏部尚书、中极殿大学士，为内阁首辅。", "img": {"src": "portraits/gaogong.webp", "w": 240, "h": 383, "file": "File:高拱.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E9%AB%98%E6%8B%B1.jpg", "license": "Public domain", "artist": "明人繪"}}, "lizhi": {"title": "李贽", "revid": 89187944, "date": "2025-09-18", "brief": "李贽（zhì）（1527年11月19日—1602年5月7日），初姓林，名载贽，后改姓李，改名贽，字宏甫，号卓吾，又号温陵居士、笃吾、百泉居士、宏父、思斋、龙湖叟、秃翁等，出身福…", "img": {"src": "portraits/lizhi.webp", "w": 240, "h": 356, "file": "File:Li Zhi.jpg", "page": "https://commons.wikimedia.org/wiki/File:Li_Zhi.jpg", "license": "CC BY-SA 3.0", "artist": "User:曳杖行歌意欲仙"}}, "dongqichang": {"title": "董其昌", "revid": 93862764, "date": "2026-08-12", "brief": "董其昌（1555年2月10日—1636年10月26日），字玄宰，号思白、思翁，别号香光居士，直隶华亭县（今上海松江区）人。明朝政治人物，书画家。", "img": {"src": "portraits/dongqichang.webp", "w": 240, "h": 223, "file": "File:董其昌.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E8%91%A3%E5%85%B6%E6%98%8C.jpg", "license": "Public domain", "artist": "清 徐璋"}}, "wuchengen": {"title": "吴承恩", "revid": 93826396, "date": "2026-08-09", "brief": "吴承恩（1506年—1582年），字汝忠，号射阳山人，或射阳居士，淮安府山阳县（今江苏省淮安市淮安区）人，祖籍江苏省涟水县，明代文学家，咸信为《西游记》作者。", "img": {"src": "portraits/wuchengen.webp", "w": 240, "h": 180, "file": "File:20240811 Bust of Wu Cheng’en.jpg", "page": "https://commons.wikimedia.org/wiki/File:20240811_Bust_of_Wu_Cheng%E2%80%99en.jpg", "license": "CC BY-SA 4.0", "artist": "Yumeto"}}, "tangyin": {"title": "唐寅", "revid": 94642288, "date": "2026-09-29", "brief": "唐寅（1470年3月6日—1524年1月7日），字伯虎，又字子畏，以字行，号六如居士、桃花庵主、逃禅仙吏、鲁国唐生等，直隶苏州府吴县人，明代画家、文学家。吴中四才子之一。", "img": {"src": "portraits/tangyin.webp", "w": 240, "h": 447, "file": "File:唐寅.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E5%94%90%E5%AF%85.jpg", "license": "Public domain", "artist": "張靈繪"}}, "duoergun": {"title": "多爾袞", "revid": 94448718, "date": "2026-09-19", "brief": "多尔衮（满语：ᡩᠣᡵᡤᠣᠨ，穆麟德转写：Dorgon，1612年11月17日—1650年12月31日），满洲爱新觉罗氏，清朝初年宗室、皇父摄政王、权臣、八旗领袖、清朝入关后奠基…", "img": {"src": "portraits/duoergun.webp", "w": 240, "h": 329, "file": "File:Dorgon, the Prince Rui (17th century).jpg", "page": "https://commons.wikimedia.org/wiki/File:Dorgon,_the_Prince_Rui_(17th_century).jpg", "license": "Public domain", "artist": "Unknown author"}}, "xiaozhuang": {"title": "孝莊文皇后", "revid": 94409582, "date": "2026-09-17", "brief": "孝庄太皇太后（满语：ᡥᡳᠶᠣᠣᡧᡠᠩᡤᠠᠠᠮᠪᠠᠯᡳᠩᡤᡡᡤᡝᠩᡤᡳᠶᡝᠨᡧᡠ᠌ᡥᡡᠸᠠᠩᡥᡝᠣ，穆麟德转写：hiyoošunggaambalinggūgenggiyenšuh…", "img": {"src": "portraits/xiaozhuang.webp", "w": 240, "h": 505, "file": "File:Empress XiaoZhuang.PNG", "page": "https://commons.wikimedia.org/wiki/File:Empress_XiaoZhuang.PNG", "license": "Public domain", "artist": "佚名"}}, "wusangui": {"title": "吴三桂", "revid": 93998517, "date": "2026-08-22", "brief": "吴三桂（1612年6月8日—1678年10月2日），字长伯，辽西（今辽宁绥中县）人，明末清初政治家、军事家，为明清改朝换代的关键人物之一。", "img": {"src": "portraits/wusangui.webp", "w": 240, "h": 318, "file": "File:Wu Sangui.jpg", "page": "https://commons.wikimedia.org/wiki/File:Wu_Sangui.jpg", "license": "Public domain", "artist": "Author in Qing Dynasty"}}, "shilang": {"title": "施琅", "revid": 93822791, "date": "2026-08-09", "brief": "施琅（白话字：SiLông，1621年3月7日—1696年4月22日），本名施郎，降清后改名“施琅”，字尊侯，号琢公，福建泉州府晋江县（今晋江市龙湖镇衙口村）人，祖籍河南固始。", "img": {"src": "portraits/shilang.webp", "w": 240, "h": 320, "file": "File:Generaal Shi Lang met een gezelschap hoogwaardigheidsbekleders bij een waterput aan zee (cropped).jpg", "page": "https://commons.wikimedia.org/wiki/File:Generaal_Shi_Lang_met_een_gezelschap_hoogwaardigheidsbekleders_bij_een_waterput_aan_zee_(cropped).jpg", "license": "Public domain", "artist": "AnonymousUnknown author"}}, "niangengyao": {"title": "年羹尧", "revid": 94384038, "date": "2026-09-16", "brief": "年羹尧（1680年3月26日—1726年1月13日），字亮工，号双峯，汉军镶白旗人，雍正元年抬入汉军镶黄旗，籍辽东广宁，先祖原居安徽怀远，同进士出身，清朝康熙和雍正年间重要将领…", "img": {"src": "portraits/niangengyao.webp", "w": 240, "h": 364, "file": "File:年羹尧.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E5%B9%B4%E7%BE%B9%E5%B0%A7.jpg", "license": "Public domain", "artist": "Unknown author"}}, "heshen": {"title": "和珅", "revid": 93774979, "date": "2026-08-05", "brief": "和珅（满语：ᡥᡝᡧᡝᠨ，穆麟德转写：Hešen；1750年7月1日—1799年2月22日），清朝官员，满洲钮祜禄氏，字致斋，自号嘉乐堂、十笏园、绿野亭主人，原名善保，一作善宝。", "img": {"src": "portraits/heshen.webp", "w": 240, "h": 446, "file": "File:Hesen.jpg", "page": "https://commons.wikimedia.org/wiki/File:Hesen.jpg", "license": "Public domain", "artist": "Unknown author"}}, "jixiaolan": {"title": "紀昀", "revid": 92562099, "date": "2026-05-07", "brief": "纪昀（1724年8月3日—1805年3月14日），字晓岚，以字行，号石云、观弈道人、孤石老人、河间才子，直隶省河间府献县（今河北省沧州市献县）人，清代乾隆年间学者，政治人物。", "img": {"src": "portraits/jixiaolan.webp", "w": 240, "h": 345, "file": "File:Yueweicaotang.JPG", "page": "https://commons.wikimedia.org/wiki/File:Yueweicaotang.JPG", "license": "CC BY-SA 3.0", "artist": "User:Gisling"}}, "dengshichang": {"title": "邓世昌", "revid": 94110381, "date": "2026-08-30", "brief": "邓世昌（1849年10月4日—1894年9月17日），原名永昌，字正卿，谥壮节，广东广州番禺龙导尾人（今广东省广州市海珠区龙珠直街龙延里2号），清帝国后期海军将领，官至北洋水师…", "img": {"src": "portraits/dengshichang.webp", "w": 240, "h": 330, "file": "File:DengXiChang CHN.png", "page": "https://commons.wikimedia.org/wiki/File:DengXiChang_CHN.png", "license": "Public domain", "artist": "佚名"}}, "chenjiageng": {"title": "陈嘉庚", "revid": 93845708, "date": "2026-08-11", "brief": "陈嘉庚（1874年10月21日—1961年8月12日），原名甲庚，字科次，福建同安人，祖籍淮南固始（今河南省信阳市固始县）华人企业家，慈善家，华侨领袖。", "img": {"src": "portraits/chenjiageng.webp", "w": 240, "h": 365, "file": "File:陈嘉庚2.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E9%99%88%E5%98%89%E5%BA%9A2.jpg", "license": "Public domain", "artist": "Unknown author"}}, "nieer": {"title": "聂耳", "revid": 93761659, "date": "2026-08-04", "brief": "聂耳（1912年2月14日—1935年7月17日），原名聂守信，字子义（亦作紫艺），中国音乐家，籍贯云南玉溪，出生并成长于昆明。", "img": {"src": "portraits/nieer.webp", "w": 240, "h": 375, "file": "File:聂耳遗像 1935-7.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E8%81%82%E8%80%B3%E9%81%97%E5%83%8F_1935-7.jpg", "license": "Public domain", "artist": "《联华画报》"}}, "xianxinghai": {"title": "冼星海", "revid": 94513758, "date": "2026-09-23", "brief": "冼星海（1905年6月13日—1945年10月30日），曾用名黄训、孔宇，祖籍广东番禺，出生于澳门，中华民国作曲家、钢琴家，其作品中《黄河大合唱》最广为人知。", "img": {"src": "portraits/xianxinghai.webp", "w": 240, "h": 318, "file": "File:Xianxinghai.jpg", "page": "https://commons.wikimedia.org/wiki/File:Xianxinghai.jpg", "license": "Public domain", "artist": "Unknown author"}}, "qianweichang": {"title": "钱伟长", "revid": 94232759, "date": "2026-09-07", "brief": "钱伟长（1913年10月9日—2010年7月30日），男，江苏无锡人，中国力学家、应用数学家、教育家，中国科学院院士，原副国级领导人。", "img": {"src": "portraits/qianweichang.webp", "w": 240, "h": 371, "file": "File:钱伟长院士.jpg", "page": "https://commons.wikimedia.org/wiki/File:%E9%92%B1%E4%BC%9F%E9%95%BF%E9%99%A2%E5%A3%AB.jpg", "license": "Public domain", "artist": "Unknown author"}}, "tongdizhou": {"title": "童第周", "revid": 93760259, "date": "2026-08-03", "brief": "童第周（1902年5月28日—1979年3月30日），字蔚荪，浙江鄞县人，中国实验胚胎学家，动物克隆研究的先驱。", "img": {"src": "portraits/tongdizhou.webp", "w": 240, "h": 347, "file": "File:Tong di zhou 1955.jpg", "page": "https://commons.wikimedia.org/wiki/File:Tong_di_zhou_1955.jpg", "license": "Public domain", "artist": "Xin Hua News Agence"}}};
